-- ---------------------------------------------------------------------------
-- data.restore
--
-- Separate from every delete permission on purpose. A manager who can delete a
-- customer record should not be the one who quietly puts it back.
-- ---------------------------------------------------------------------------

create or replace function provision_org_roles(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into roles (org_id, key, name, is_system, permissions) values
  (p_org_id, 'owner', 'Owner', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.close', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.approve_unlimited', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'user.view_cost_rates', true,
    'role.manage', true, 'org.manage_settings', true, 'audit.view', true,
    'data.restore', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  (p_org_id, 'manager', 'Manager', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'audit.view', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  -- No price.view: a crew lead runs the work, not the commercials.
  (p_org_id, 'crew_lead', 'Crew Lead', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true, 'inventory.transfer', true,
    'equipment.place', true,
    'time.log_others', true
  )),

  (p_org_id, 'technician', 'Technician', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true,
    'equipment.place', true
  )),

  -- Keeps the books, so needs the price but never the margin conversation.
  -- audit.view lets them read the trail; nothing here lets them change it.
  (p_org_id, 'bookkeeper', 'Bookkeeper', true, jsonb_build_object(
    'job.view_all', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'mileage.view_all', true, 'time.view_all', true,
    'audit.view', true, 'price.view', true, 'costing.view', true, 'export.run', true,
    'job.close', true
  ))
  on conflict (org_id, key) do nothing;
end;
$$;

-- Orgs that already exist get the flag too, or the owner locks themselves out
-- of the screen this migration is for.
update roles
   set permissions = permissions || jsonb_build_object('data.restore', true)
 where key = 'owner'
   and coalesce((permissions ->> 'data.restore')::boolean, false) = false;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select on deletable_tables to authenticated';
  end if;
end $$;

-- ===========================================================
-- 0023_job_authoring.sql
-- ===========================================================
-- 0023 Creating and editing a job
--
-- Putting work on the calendar is three writes that have to agree: the job,
-- the work days behind it, and who is going. Doing that from a client leaves
-- half-made jobs behind whenever a tab closes at the wrong moment, and leaves
-- each client free to invent its own idea of what a valid job is.
--
-- So it is one function per intent, and the rules sit with the data:
--
--   * a site has to belong to the customer it is booked under;
--   * a multi-day job produces one visit per day, not one visit;
--   * nobody is assigned over approved time off, ever;
--   * a double booking is refused but can be overridden deliberately, because
--     sometimes two short jobs really do fit and only the manager knows.

-- ---------------------------------------------------------------------------
-- Work days
-- ---------------------------------------------------------------------------

-- Rebuilds the visits for a job from its scheduled range: one per calendar
-- day, each keeping the job's own start and end times. A one-day job gets
-- exactly one. Visits that already have work recorded against them are left
-- alone rather than silently replaced.
create or replace function rebuild_job_visits(p_job_id uuid)
returns int
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_job jobs;
  v_day date;
  v_last date;
  v_seq int := 0;
  v_start timestamptz;
  v_end timestamptz;
begin
  select * into v_job from jobs where id = p_job_id;
  if not found then
    raise exception 'No such job' using errcode = '02000';
  end if;
  if v_job.scheduled_start is null then
    return 0;
  end if;

  -- Anything already under way keeps its visit; re-cutting the days under a
  -- crew who are standing in the basement is not a scheduling change.
  delete from job_visits
   where job_id = p_job_id
     and status = 'scheduled'
     and not exists (select 1 from time_entries t where t.visit_id = job_visits.id);

  v_day := (v_job.scheduled_start at time zone 'UTC')::date;
  v_last := (coalesce(v_job.scheduled_end, v_job.scheduled_start) at time zone 'UTC')::date;

  while v_day <= v_last loop
    v_seq := v_seq + 1;

    -- Keep the job's clock times, moved onto this day.
    v_start := v_day + (v_job.scheduled_start at time zone 'UTC')::time;
    v_end := v_day + (coalesce(v_job.scheduled_end, v_job.scheduled_start + interval '4 hours')
                      at time zone 'UTC')::time;
    if v_end <= v_start then
      v_end := v_start + interval '4 hours';
    end if;

    insert into job_visits (org_id, job_id, seq, scheduled_start, scheduled_end)
    values (v_job.org_id, p_job_id, v_seq, v_start, v_end)
    on conflict (job_id, seq) do update
      set scheduled_start = excluded.scheduled_start,
          scheduled_end = excluded.scheduled_end;

    v_day := v_day + 1;
  end loop;

  -- A job that got shorter should not keep the days it no longer runs.
  delete from job_visits
   where job_id = p_job_id
     and seq > v_seq
     and status = 'scheduled'
     and not exists (select 1 from time_entries t where t.visit_id = job_visits.id);

  return v_seq;
end;
$fn$;

comment on function rebuild_job_visits(uuid) is
  'One visit per calendar day the job runs, keeping its clock times. Leaves '
  'visits that already have time logged against them.';

-- ---------------------------------------------------------------------------
-- Who is going
-- ---------------------------------------------------------------------------

create or replace function set_job_crew(
  p_job_id uuid,
  p_user_ids uuid[],
  p_force boolean default false
)
returns int
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_job jobs;
  v_user uuid;
  v_name text;
  v_conflicts text[];
  v_hard text[] := '{}';
  v_soft text[] := '{}';
  v_kept int := 0;
begin
  if not has_permission('job.assign') then
    raise exception 'Not permitted: assigning work needs job.assign'
      using errcode = '42501';
  end if;

  select * into v_job from jobs where id = p_job_id and org_id = auth_org_id()
    and deleted_at is null;
  if not found then
    raise exception 'No such job' using errcode = '02000';
  end if;
  if v_job.scheduled_start is null then
    raise exception 'Put the job on the calendar before putting people on it'
      using errcode = '22023';
  end if;

  -- Check everyone first and report together. Finding out about the second
  -- clash only after fixing the first is how a three-person crew takes three
  -- attempts to book.
  foreach v_user in array coalesce(p_user_ids, '{}'::uuid[]) loop
    select full_name into v_name from profiles
     where id = v_user and org_id = v_job.org_id and is_active;
    if v_name is null then
      raise exception 'That person is not on the staff list' using errcode = '23503';
    end if;

    v_conflicts := scheduling_conflicts(
      v_user, v_job.scheduled_start,
      coalesce(v_job.scheduled_end, v_job.scheduled_start), p_job_id);

    if v_conflicts is not null then
      -- Approved time off is not a judgement call: they are not there.
      if exists (select 1 from unnest(v_conflicts) c where c ilike '%time off%') then
        v_hard := array_append(v_hard, v_name || ': ' ||
          (select string_agg(c, '; ') from unnest(v_conflicts) c where c ilike '%time off%'));
      end if;
      if exists (select 1 from unnest(v_conflicts) c where c not ilike '%time off%') then
        v_soft := array_append(v_soft, v_name || ': ' ||
          (select string_agg(c, '; ') from unnest(v_conflicts) c where c not ilike '%time off%'));
      end if;
    end if;
  end loop;

  if array_length(v_hard, 1) > 0 then
    raise exception 'Approved time off. %', array_to_string(v_hard, ' / ')
      using errcode = '23514';
  end if;
  if array_length(v_soft, 1) > 0 and not p_force then
    raise exception 'Already booked. %', array_to_string(v_soft, ' / ')
      using errcode = '23505';
  end if;

  -- Anyone dropped from the crew loses their row; anyone kept keeps the
  -- acceptance they already gave, so adding a fourth person does not make the
  -- other three answer again.
  delete from job_assignments
   where job_id = p_job_id
     and not (user_id = any (coalesce(p_user_ids, '{}'::uuid[])));

  foreach v_user in array coalesce(p_user_ids, '{}'::uuid[]) loop
    insert into job_assignments (org_id, job_id, user_id, assigned_by)
    values (v_job.org_id, p_job_id, v_user, auth_user_id())
    on conflict (job_id, user_id, visit_id) do nothing;
  end loop;

  select count(*) into v_kept from job_assignments where job_id = p_job_id;

  -- Having people on it is what "assigned" means, so keep the status honest
  -- in both directions.
  if v_kept > 0 and v_job.status = 'scheduled' then
    perform transition_job(p_job_id, 'assigned', 'Crew set');
  elsif v_kept = 0 and v_job.status = 'assigned' then
    perform transition_job(p_job_id, 'scheduled', 'Crew cleared');
  end if;

  return v_kept;
end;
$fn$;

comment on function set_job_crew(uuid, uuid[], boolean) is
  'Replaces a job''s crew. Refuses approved time off outright; refuses a '
  'double booking unless p_force. Keeps the acceptance of anyone already on.';

-- ---------------------------------------------------------------------------
-- Creating
-- ---------------------------------------------------------------------------

create or replace function create_job(
  p_customer_id uuid,
  p_site_id uuid,
  p_title text,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_description text default null,
  p_template_id uuid default null,
  p_priority job_priority default 'normal',
  p_quoted_price numeric default null,
  p_crew uuid[] default '{}'
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_job jobs;
  v_ok int;
begin
  if not has_permission('job.edit') then
    raise exception 'Not permitted: creating a job needs job.edit'
      using errcode = '42501';
  end if;

  if p_title is null or btrim(p_title) = '' then
    raise exception 'A job needs a title' using errcode = '22023';
  end if;
  if p_scheduled_start is null then
    raise exception 'A job needs a day' using errcode = '22023';
  end if;
  if p_scheduled_end is not null and p_scheduled_end < p_scheduled_start then
    raise exception 'The job ends before it starts' using errcode = '22023';
  end if;

  -- A site under the wrong customer is the mistake that produces a job
  -- history nobody can trust, so it is refused rather than tidied later.
  select count(*) into v_ok from sites
   where id = p_site_id and customer_id = p_customer_id and org_id = v_org
     and deleted_at is null;
  if v_ok = 0 then
    raise exception 'That site does not belong to that customer'
      using errcode = '23503';
  end if;

  insert into jobs (
    org_id, customer_id, site_id, template_id, title, description,
    priority, scheduled_start, scheduled_end, quoted_price, created_by
  ) values (
    v_org, p_customer_id, p_site_id, p_template_id, btrim(p_title),
    nullif(btrim(coalesce(p_description, '')), ''),
    coalesce(p_priority, 'normal'), p_scheduled_start, p_scheduled_end,
    p_quoted_price, auth_user_id()
  )
  returning * into v_job;

  perform rebuild_job_visits(v_job.id);

  -- A job created on the calendar is scheduled, not a draft: the draft state
  -- is for work being quoted, and this screen is for work being booked.
  perform transition_job(v_job.id, 'scheduled', 'Created on the calendar');

  if array_length(p_crew, 1) > 0 then
    perform set_job_crew(v_job.id, p_crew);
  end if;

  select * into v_job from jobs where id = v_job.id;
  return v_job;
end;
$fn$;

comment on function create_job(uuid, uuid, text, timestamptz, timestamptz, text, uuid, job_priority, numeric, uuid[]) is
  'Creates a job, cuts its work days, schedules it and optionally assigns a '
  'crew — in one transaction, so a half-made job cannot be left behind.';

-- ---------------------------------------------------------------------------
-- Editing
-- ---------------------------------------------------------------------------

-- Moving a job is not the same edit as renaming one: the work days have to
-- follow, and everyone who agreed to the old time has to agree again.
create or replace function reschedule_job(
  p_job_id uuid,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_reason text default null
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare v_job jobs;
begin
  if not has_permission('job.edit') then
    raise exception 'Not permitted: moving a job needs job.edit'
      using errcode = '42501';
  end if;

  select * into v_job from jobs
   where id = p_job_id and org_id = auth_org_id() and deleted_at is null;
  if not found then
    raise exception 'No such job' using errcode = '02000';
  end if;
  if p_scheduled_end is not null and p_scheduled_end < p_scheduled_start then
    raise exception 'The job ends before it starts' using errcode = '22023';
  end if;

  update jobs
     set scheduled_start = p_scheduled_start,
         scheduled_end = p_scheduled_end
   where id = p_job_id;

  perform rebuild_job_visits(p_job_id);

  -- They agreed to a Tuesday. This is a Thursday.
  if p_scheduled_start is distinct from v_job.scheduled_start
     or p_scheduled_end is distinct from v_job.scheduled_end then
    update job_assignments
       set acceptance_status = 'pending', responded_at = null
     where job_id = p_job_id
       and acceptance_status <> 'pending';

    insert into job_status_history (org_id, job_id, from_status, to_status, changed_by, note)
    values (v_job.org_id, p_job_id, v_job.status, v_job.status, auth_user_id(),
            coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Rescheduled'));
  end if;

  select * into v_job from jobs where id = p_job_id;
  return v_job;
end;
$fn$;

comment on function reschedule_job(uuid, timestamptz, timestamptz, text) is
  'Moves a job, re-cuts its work days and resets everyone''s acceptance — '
  'they agreed to the old time, not this one.';

-- ===========================================================
-- 0024_decisions.sql
-- ===========================================================
-- 0024 Answering the crew
--
-- The field app lets a crew member ask to move a job and ask for time off.
-- Until now nothing could answer either: `decide_reschedule` existed but
-- moved a job without re-cutting its work days, and time off had no decision
-- function at all — only a raw update that could leave `decided_by` blank and
-- a decline with no reason.
--
-- A request nobody can answer is worse than no request: the crew learn the
-- app does not work and go back to phoning.

-- ---------------------------------------------------------------------------
-- Moving a job un-agrees it
-- ---------------------------------------------------------------------------

-- Accepting is agreeing to a time. Change the time and the agreement lapses,
-- which means the job is back to waiting on people rather than settled.
insert into job_transitions (from_status, to_status, required_permission, guard, enabled)
values ('accepted', 'assigned', 'job.assign', null, true)
on conflict (from_status, to_status) do update
  set required_permission = excluded.required_permission,
      enabled = true;

-- Used wherever a job's time changes. Resets every acceptance — not only the
-- person who asked, because the others agreed to the old time too — and steps
-- the status back if the job had been fully accepted.
create or replace function unaccept_job(p_job_id uuid, p_note text default null)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare v_status job_status;
begin
  update job_assignments
     set acceptance_status = 'pending', responded_at = null
   where job_id = p_job_id
     and acceptance_status <> 'pending';

  select status into v_status from jobs where id = p_job_id;

  -- Only the office can put a job back to 'assigned'. Anyone else changing a
  -- time still un-agrees it; the status simply stays where it was rather than
  -- the whole decision failing on a permission check.
  if v_status = 'accepted' and has_permission('job.assign') then
    perform transition_job(p_job_id, 'assigned',
                           coalesce(p_note, 'Time changed — everyone re-accepts'));
  end if;
end;
$fn$;

comment on function unaccept_job(uuid, text) is
  'Resets every acceptance on a job and steps it back from accepted to '
  'assigned. Called wherever a job''s time changes.';

-- 0023 reset acceptance itself; route it through the shared rule instead, so
-- the status follows too.
create or replace function reschedule_job(
  p_job_id uuid,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_reason text default null
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_job jobs;
  v_moved boolean;
begin
  if not has_permission('job.edit') then
    raise exception 'Not permitted: moving a job needs job.edit'
      using errcode = '42501';
  end if;

  select * into v_job from jobs
   where id = p_job_id and org_id = auth_org_id() and deleted_at is null;
  if not found then
    raise exception 'No such job' using errcode = '02000';
  end if;
  if p_scheduled_end is not null and p_scheduled_end < p_scheduled_start then
    raise exception 'The job ends before it starts' using errcode = '22023';
  end if;

  v_moved := p_scheduled_start is distinct from v_job.scheduled_start
          or p_scheduled_end is distinct from v_job.scheduled_end;

  update jobs
     set scheduled_start = p_scheduled_start,
         scheduled_end = p_scheduled_end
   where id = p_job_id;

  perform rebuild_job_visits(p_job_id);

  if v_moved then
    perform unaccept_job(p_job_id, coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Rescheduled'));

    insert into job_status_history (org_id, job_id, from_status, to_status, changed_by, note)
    values (v_job.org_id, p_job_id, v_job.status, v_job.status, auth_user_id(),
            coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Rescheduled'));
  end if;

  select * into v_job from jobs where id = p_job_id;
  return v_job;
end;
$fn$;

-- ---------------------------------------------------------------------------
-- Deciding a reschedule request
-- ---------------------------------------------------------------------------

-- Replaces the 0012 version. Two things were wrong with it: approving moved
-- the job without re-cutting its work days, so a three-day job kept the old
-- three days on everyone's calendar; and it wrote `jobs.status` directly,
-- which is the one thing nothing in this schema is allowed to do.
--
-- It also now takes the new time from whoever is deciding. The crew member
-- knows Tuesday does not work; the office is the one who knows what else is
-- booked, so they pick the slot.
create or replace function decide_reschedule(
  p_request_id uuid,
  p_approve boolean,
  p_reason text default null,
  p_new_start timestamptz default null,
  p_new_end timestamptz default null
)
returns reschedule_requests
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_request reschedule_requests;
  v_start timestamptz;
  v_end timestamptz;
begin
  if not has_permission('reschedule.decide') then
    raise exception 'Not permitted: deciding this needs reschedule.decide'
      using errcode = '42501';
  end if;

  select * into v_request from reschedule_requests
   where id = p_request_id and org_id = auth_org_id()
   for update;
  if not found then
    raise exception 'No such request' using errcode = '02000';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'That request was already %', v_request.status
      using errcode = '22023';
  end if;
  if not p_approve and (p_reason is null or btrim(p_reason) = '') then
    raise exception 'Say why, so they are not left guessing'
      using errcode = '22023';
  end if;

  -- The decider's time wins; the requester's proposal is the fallback.
  v_start := coalesce(p_new_start, v_request.proposed_start);
  v_end := coalesce(p_new_end, v_request.proposed_end);

  if p_approve and v_start is null then
    raise exception 'Approving needs a new time — they asked to move it, not to drop it'
      using errcode = '22023';
  end if;

  update reschedule_requests
     set status = case when p_approve then 'approved' else 'declined' end::reschedule_status,
         decided_by = auth_user_id(),
         decided_at = now(),
         decision_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where id = p_request_id
   returning * into v_request;

  if p_approve then
    -- Goes through the same door the office uses, so the work days follow and
    -- everyone re-accepts.
    perform reschedule_job(v_request.job_id, v_start, v_end,
                           'Moved after a reschedule request');
  else
    -- Declined: the job stays where it is, and the person who asked still has
    -- to answer it.
    update job_assignments
       set acceptance_status = 'pending', responded_at = null
     where id = v_request.assignment_id;
  end if;

  return v_request;
end;
$fn$;

comment on function decide_reschedule(uuid, boolean, text, timestamptz, timestamptz) is
  'Approve with a new time, or decline with a reason. Approving moves the job '
  'through reschedule_job(), so the work days are re-cut and every acceptance '
  'resets.';

-- ---------------------------------------------------------------------------
-- Deciding time off
-- ---------------------------------------------------------------------------

-- The jobs someone is already booked on inside a window. Shown to the person
-- asking before they send it, and to whoever is deciding — the same list, so
-- neither side is surprised.
create or replace function time_off_clashes(p_request_id uuid)
returns table (
  job_id uuid,
  job_number text,
  title text,
  scheduled_start timestamptz,
  scheduled_end timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare v_req time_off;
begin
  select * into v_req from time_off
   where id = p_request_id and org_id = auth_org_id();
  if not found then
    return;
  end if;

  -- Their own request, or someone whose job it is to decide it.
  if v_req.user_id <> auth_user_id() and not has_permission('timeoff.manage') then
    raise exception 'Not permitted' using errcode = '42501';
  end if;

  return query
  select j.id, j.job_number, j.title, j.scheduled_start, j.scheduled_end
    from job_assignments a
    join jobs j on j.id = a.job_id
   where a.user_id = v_req.user_id
     and j.deleted_at is null
     and j.status not in ('cancelled', 'closed')
     and j.scheduled_start is not null
     and tstzrange(j.scheduled_start, coalesce(j.scheduled_end, j.scheduled_start), '[]')
         && tstzrange(v_req.starts_at, v_req.ends_at, '[]')
   order by j.scheduled_start;
end;
$fn$;

comment on function time_off_clashes(uuid) is
  'The jobs this person is already booked on inside the requested window. '
  'Same list for the requester and the decider.';

create or replace function decide_time_off(
  p_request_id uuid,
  p_approve boolean,
  p_reason text default null
)
returns time_off
language plpgsql
security definer
set search_path = public
as $fn$
declare v_req time_off;
begin
  if not has_permission('timeoff.manage') then
    raise exception 'Not permitted: deciding time off needs timeoff.manage'
      using errcode = '42501';
  end if;

  select * into v_req from time_off
   where id = p_request_id and org_id = auth_org_id()
   for update;
  if not found then
    raise exception 'No such request' using errcode = '02000';
  end if;
  if v_req.status <> 'requested' then
    raise exception 'That request was already %', v_req.status using errcode = '22023';
  end if;

  -- A decline with no reason is how people stop asking, and then stop telling
  -- you they will not be there.
  if not p_approve and (p_reason is null or btrim(p_reason) = '') then
    raise exception 'Say why. They read this on their phone.'
      using errcode = '22023';
  end if;

  -- Deliberately does NOT refuse over a booked job, and deliberately does not
  -- move that job either. Approving records that the person will not be
  -- there; reassigning someone else's work is a decision, not a side effect.
  -- From this moment the scheduling conflict check refuses new bookings for
  -- those dates.
  update time_off
     set status = case when p_approve then 'approved' else 'declined' end::time_off_status,
         decided_by = auth_user_id(),
         decided_at = now(),
         decision_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where id = p_request_id
   returning * into v_req;

  return v_req;
end;
$fn$;

comment on function decide_time_off(uuid, boolean, text) is
  'Approve or decline time off, recording who and when. A decline needs a '
  'reason. Never moves work that is already booked — that is a separate '
  'decision.';

-- ===========================================================
-- 0025_consumables.sql
-- ===========================================================
-- 0025 Consumables: what a pack is, and where its cost lands
--
-- The schema had two kinds of thing: counted stock and serialised assets. A
-- box of contractor bags is neither. It is counted like stock but it travels
-- and gets used up like equipment, and nobody on a crew can tell you how many
-- bags are left in the box.
--
-- Three modes, one column:
--
--   single_use  masks, gloves, coveralls     counted out, costed to the job
--   bulk        bags, poly sheeting, chemical one container, opened once,
--                                            cost split across what it served
--   returnable  cords, buckets               counted out, counted back, costs
--                                            nothing because it comes home
--
-- THREE ASSUMPTIONS ARE BAKED IN HERE. They were open questions; they are
-- answered this way because the alternatives produce numbers that are not
-- true. Say so and they change — each is a small migration, not a rewrite.
--
--   1. A pack is open or finished. There is no part-used state and no "how
--      full is it" prompt. That question produces a guess, and the whole
--      reason for the pack model is to stop asking it.
--
--   2. PPE is costed to the job, never to the person. What a coverall cost
--      belongs on the job's margin. Who wore it is a payroll and safety
--      question that this app is not the place for.
--
--   3. A pack lives at a stock location — in practice a van — and can be
--      moved. "Which van has an open box of bags" is the question actually
--      asked on a Tuesday morning.

create type consumption_mode as enum ('single_use', 'bulk', 'returnable');

alter table inventory_items
  add column if not exists consumption_mode consumption_mode not null default 'single_use';

comment on column inventory_items.consumption_mode is
  'How this item is consumed: counted per job, opened as a pack, or returned.';

-- ---------------------------------------------------------------------------
-- Open packs
-- ---------------------------------------------------------------------------

create table stock_packs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  item_id uuid not null references inventory_items(id),
  -- Where the physical container is right now.
  location_id uuid not null references stock_locations(id),
  opened_at timestamptz not null default now(),
  opened_by uuid references profiles(id),
  -- What the container cost, snapshotted when it came off the shelf. The
  -- item's average cost moves with every receipt; this one must not, or a
  -- pack opened in March gets re-costed in July.
  unit_cost numeric(12,4) not null default 0,
  finished_at timestamptz,
  finished_by uuid references profiles(id),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on stock_packs (org_id, location_id) where finished_at is null;
create index on stock_packs (item_id);

-- Which jobs a pack served. Append-only: a job that used a pack used it, and
-- un-saying that later would quietly move money between jobs.
create table stock_pack_jobs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  pack_id uuid not null references stock_packs(id) on delete cascade,
  job_id uuid not null references jobs(id) on delete cascade,
  first_used_at timestamptz not null default now(),
  logged_by uuid references profiles(id),
  unique (pack_id, job_id)
);

create index on stock_pack_jobs (job_id);

select attach_updated_at('stock_packs');
select enable_rls('stock_packs');
select enable_rls('stock_pack_jobs');

create policy stock_packs_select on stock_packs for select
  using (org_id = auth_org_id());
create policy stock_packs_write on stock_packs for all
  using (org_id = auth_org_id() and has_permission('inventory.log_usage'))
  with check (org_id = auth_org_id() and has_permission('inventory.log_usage'));

-- Append-only, like every other history table here.
create policy stock_pack_jobs_select on stock_pack_jobs for select
  using (org_id = auth_org_id());
create policy stock_pack_jobs_insert on stock_pack_jobs for insert
  with check (org_id = auth_org_id() and has_permission('inventory.log_usage'));

select attach_audit('stock_packs');

-- ---------------------------------------------------------------------------
-- Opening, using, finishing
-- ---------------------------------------------------------------------------

-- Opening a pack is the moment the stock leaves the shelf. One movement, no
-- job attached — which job pays is not known yet and pretending otherwise is
-- how the first job to touch a box ends up wearing all of it.
create or replace function open_pack(
  p_item_id uuid,
  p_location_id uuid,
  p_job_id uuid default null,
  p_notes text default null
)
returns stock_packs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_item inventory_items;
  v_pack stock_packs;
  v_on_hand numeric;
begin
  if not has_permission('inventory.log_usage') then
    raise exception 'Not permitted: opening a pack needs inventory.log_usage'
      using errcode = '42501';
  end if;

  select * into v_item from inventory_items
   where id = p_item_id and org_id = v_org and deleted_at is null;
  if not found then
    raise exception 'No such item' using errcode = '02000';
  end if;
  if v_item.consumption_mode <> 'bulk' then
    raise exception '% is not something you open — it is counted out', v_item.name
      using errcode = '22023';
  end if;

  select coalesce(quantity, 0) into v_on_hand from stock_levels
   where item_id = p_item_id and location_id = p_location_id;
  if coalesce(v_on_hand, 0) < 1 then
    raise exception 'No % left at that location to open', v_item.name
      using errcode = '23514';
  end if;

  insert into stock_packs (org_id, item_id, location_id, opened_by, unit_cost, notes)
  values (v_org, p_item_id, p_location_id, auth_user_id(), v_item.average_cost,
          nullif(btrim(coalesce(p_notes, '')), ''))
  returning * into v_pack;

  insert into stock_movements (
    org_id, item_id, kind, from_location_id, quantity, unit_cost,
    reference_table, reference_id, reason, created_by
  ) values (
    v_org, p_item_id, 'usage', p_location_id, 1, v_item.average_cost,
    'stock_packs', v_pack.id, 'Pack opened', auth_user_id()
  );

  if p_job_id is not null then
    perform use_pack_on_job(v_pack.id, p_job_id);
  end if;

  return v_pack;
end;
$fn$;

comment on function open_pack(uuid, uuid, uuid, text) is
  'Takes one container off the shelf and starts a pack. The cost parks on the '
  'pack until it is finished, because which jobs pay is not known yet.';

-- Says this job used that pack. Cheap, idempotent, and the only thing the
-- crew are ever asked about a pack.
create or replace function use_pack_on_job(p_pack_id uuid, p_job_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare v_pack stock_packs;
begin
  if not has_permission('inventory.log_usage') then
    raise exception 'Not permitted: logging use needs inventory.log_usage'
      using errcode = '42501';
  end if;

  select * into v_pack from stock_packs
   where id = p_pack_id and org_id = auth_org_id();
  if not found then
    raise exception 'No such pack' using errcode = '02000';
  end if;
  if v_pack.finished_at is not null then
    raise exception 'That pack was finished on %', v_pack.finished_at::date
      using errcode = '22023';
  end if;

  insert into stock_pack_jobs (org_id, pack_id, job_id, logged_by)
  values (v_pack.org_id, p_pack_id, p_job_id, auth_user_id())
  on conflict (pack_id, job_id) do nothing;
end;
$fn$;

-- Finishing is the only quantity judgement anyone makes about a pack, and it
-- is a yes/no one: is it empty. That splits its cost across what it served.
create or replace function finish_pack(p_pack_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_pack stock_packs;
  v_jobs int;
begin
  if not has_permission('inventory.log_usage') then
    raise exception 'Not permitted: finishing a pack needs inventory.log_usage'
      using errcode = '42501';
  end if;

  select * into v_pack from stock_packs
   where id = p_pack_id and org_id = auth_org_id();
  if not found then
    raise exception 'No such pack' using errcode = '02000';
  end if;
  if v_pack.finished_at is not null then
    raise exception 'That pack is already finished' using errcode = '22023';
  end if;

  update stock_packs
     set finished_at = now(), finished_by = auth_user_id()
   where id = p_pack_id
   returning * into v_pack;

  select count(*) into v_jobs from stock_pack_jobs where pack_id = p_pack_id;

  return jsonb_build_object(
    'pack_id', p_pack_id,
    'jobs', v_jobs,
    'cost', v_pack.unit_cost,
    -- A pack nobody logged against a job costs the business, not a job. That
    -- is worth seeing rather than silently absorbing.
    'each', case when v_jobs > 0 then round(v_pack.unit_cost / v_jobs, 2) else null end
  );
end;
$fn$;

comment on function finish_pack(uuid) is
  'Marks a pack empty. Its cost then splits evenly across the jobs it served; '
  'a pack logged against no job lands on the business rather than a job.';

create or replace function move_pack(p_pack_id uuid, p_location_id uuid)
returns stock_packs
language plpgsql
security definer
set search_path = public
as $fn$
declare v_pack stock_packs;
begin
  if not has_permission('inventory.transfer') then
    raise exception 'Not permitted: moving stock needs inventory.transfer'
      using errcode = '42501';
  end if;

  update stock_packs
     set location_id = p_location_id
   where id = p_pack_id and org_id = auth_org_id() and finished_at is null
   returning * into v_pack;

  if not found then
    raise exception 'No open pack of that id here' using errcode = '02000';
  end if;
  return v_pack;
end;
$fn$;

-- ---------------------------------------------------------------------------
-- Where the cost lands
-- ---------------------------------------------------------------------------

-- An even split across the jobs a finished pack served. An open pack costs
-- nothing yet, because how many jobs it will serve is not known — and a
-- number that changes every week is not a cost, it is a rumour.
create or replace function job_pack_cost(p_job_id uuid)
returns numeric
language sql
stable
as $fn$
  select coalesce(sum(p.unit_cost / greatest(n.jobs, 1)), 0)
  from stock_pack_jobs pj
  join stock_packs p on p.id = pj.pack_id
  join lateral (
    select count(*) as jobs from stock_pack_jobs x where x.pack_id = p.id
  ) n on true
  where pj.job_id = p_job_id
    and p.finished_at is not null;
$fn$;

comment on function job_pack_cost(uuid) is
  'This job''s share of every finished pack it used. Derived, never stored.';

-- Folded into the materials line rather than added as a seventh column: a
-- pack is materials, and the costing screens and the export keep their shape.
create or replace function job_material_cost(p_job_id uuid)
returns numeric
language sql
stable
as $fn$
  select
    coalesce((
      select sum(mu.quantity * i.average_cost)
      from material_usage mu
      join inventory_items i on i.id = mu.item_id
      where mu.job_id = p_job_id
    ), 0)
    + job_pack_cost(p_job_id);
$fn$;

comment on function job_material_cost(uuid) is
  'Counted materials logged against the job, plus its share of any finished '
  'pack that served it.';

-- ---------------------------------------------------------------------------
-- What is open, and where
-- ---------------------------------------------------------------------------

create view open_packs
with (security_invoker = true)
as
select
  p.id as pack_id,
  p.org_id,
  p.item_id,
  i.sku,
  i.name,
  p.location_id,
  loc.name as location_name,
  p.opened_at,
  p.opened_by,
  p.unit_cost,
  p.notes,
  (select count(*) from stock_pack_jobs pj where pj.pack_id = p.id) as jobs_served
from stock_packs p
join inventory_items i on i.id = p.item_id
join stock_locations loc on loc.id = p.location_id
where p.finished_at is null;

comment on view open_packs is
  'Every container currently open, and which van it is on.';

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select on open_packs to authenticated';
  end if;
end $$;

-- ===========================================================
-- 0026_purchasing.sql
-- ===========================================================
-- 0026 Raising a purchase request, and approving part of one
--
-- Two problems with what was here.
--
-- First, there was no way to raise a request in one go. A client had to
-- insert the request, then its lines, then submit — three writes in an order
-- the lock trigger cares about, and a tab closed in the middle leaves an
-- empty draft nobody will ever find.
--
-- Second, and worse: the approval threshold was checked against the whole
-- request even when the approver had unticked lines. A manager with a $500
-- limit looking at a $900 request could untick the $600 item, leaving $300 —
-- and still be refused. The limit is about what is being spent, so it has to
-- be measured against what is actually being approved.

-- ---------------------------------------------------------------------------
-- The lock was too wide to let anyone approve anything
-- ---------------------------------------------------------------------------
--
-- Lines were frozen outright once a request left draft, which is right for
-- the person who raised it — what was asked for must not change quietly after
-- somebody has looked at it. But approving a request *is* writing to its
-- lines: line_status and rejection_reason live there. So the approve path
-- could never have worked, and receiving a delivered line could not either.
--
-- The rule is really about the ask, not the row: what was requested is
-- frozen; what happened to it afterwards is not.
create or replace function purchase_request_lock_check()
returns trigger
language plpgsql
as $fn$
declare v_status purchase_status;
begin
  select r.status into v_status
    from purchase_requests r
   where r.id = coalesce(new.request_id, old.request_id);

  -- While it is still being written, anything goes.
  if v_status in ('draft', 'under_review') then
    return coalesce(new, old);
  end if;

  -- After that, the decision and the receipt may be recorded; the ask may not
  -- be rewritten, and lines may not appear or vanish.
  if tg_op = 'UPDATE'
     and new.item_id is not distinct from old.item_id
     and new.description is not distinct from old.description
     and new.quantity is not distinct from old.quantity
     and new.unit is not distinct from old.unit
     and new.estimated_unit_cost is not distinct from old.estimated_unit_cost then
    return new;
  end if;

  raise exception 'What was asked for cannot change once the request is submitted'
    using errcode = '23514';
end;
$fn$;

-- What this decision would actually commit to.
create or replace function purchase_request_selected_total(
  p_request_id uuid,
  p_line_ids uuid[] default null
)
returns numeric
language sql
stable
as $fn$
  select coalesce(sum(l.quantity * coalesce(l.estimated_unit_cost, 0)), 0)
  from purchase_request_lines l
  where l.request_id = p_request_id
    and (p_line_ids is null or l.id = any (p_line_ids));
$fn$;

comment on function purchase_request_selected_total(uuid, uuid[]) is
  'The total of the lines actually being approved. A null line list means all '
  'of them.';

create or replace function decide_purchase_request(
  p_request_id uuid,
  p_approve boolean,
  p_reason text default null,
  p_approved_line_ids uuid[] default null
)
returns purchase_requests
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_request purchase_requests;
  v_total numeric;
  v_threshold numeric;
  v_approved_count int;
begin
  select * into v_request from purchase_requests
   where id = p_request_id and org_id = auth_org_id()
   for update;
  if not found then
    raise exception 'No such request' using errcode = '02000';
  end if;
  if v_request.status not in ('submitted', 'under_review') then
    raise exception 'That request is % and cannot be decided now', v_request.status
      using errcode = '22023';
  end if;

  if not has_permission('purchase.approve') then
    raise exception 'Not permitted: approving a purchase needs purchase.approve'
      using errcode = '42501';
  end if;

  if not p_approve and (p_reason is null or btrim(p_reason) = '') then
    raise exception 'Say why, so they know whether to ask differently'
      using errcode = '22023';
  end if;

  -- The threshold is read server-side, never sent by the client, and measured
  -- against the lines being approved rather than everything asked for.
  select coalesce((settings ->> 'approval_threshold')::numeric, 0)
    into v_threshold
    from organizations where id = v_request.org_id;

  v_total := purchase_request_selected_total(p_request_id, p_approved_line_ids);

  if p_approve
     and v_total > v_threshold
     and not has_permission('purchase.approve_unlimited') then
    raise exception
      'That comes to %, over the % you can approve. Take a line off, or send it to the owner.',
      to_char(v_total, 'FM999,999,990.00'), to_char(v_threshold, 'FM999,999,990.00')
      using errcode = '42501';
  end if;

  if p_approve then
    if p_approved_line_ids is null then
      update purchase_request_lines set line_status = 'approved' where request_id = p_request_id;
    else
      update purchase_request_lines
         set line_status = (case when id = any (p_approved_line_ids) then 'approved' else 'rejected' end)::purchase_line_status,
             rejection_reason = case when id = any (p_approved_line_ids) then null else p_reason end
       where request_id = p_request_id;
    end if;

    select count(*) into v_approved_count
      from purchase_request_lines
     where request_id = p_request_id and line_status = 'approved';

    if v_approved_count = 0 then
      raise exception 'Nothing is ticked — reject the request instead'
        using errcode = '22023';
    end if;
  else
    update purchase_request_lines
       set line_status = 'rejected', rejection_reason = p_reason
     where request_id = p_request_id;
  end if;

  update purchase_requests
     set status = case when p_approve then 'approved' else 'rejected' end::purchase_status,
         decided_by = auth_user_id(),
         decided_at = now(),
         decision_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where id = p_request_id
   returning * into v_request;

  return v_request;
end;
$fn$;

comment on function decide_purchase_request(uuid, boolean, text, uuid[]) is
  'Approve all or some lines, or reject with a reason. The spend limit is '
  'measured against the lines being approved, not against everything asked '
  'for.';

-- ---------------------------------------------------------------------------
-- Raising one
-- ---------------------------------------------------------------------------

create or replace function create_purchase_request(
  p_lines jsonb,
  p_job_id uuid default null,
  p_assigned_to uuid default null,
  p_needed_by date default null,
  p_notes text default null,
  p_supplier_id uuid default null,
  p_submit boolean default true
)
returns purchase_requests
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_request purchase_requests;
  v_line jsonb;
begin
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'A request with nothing on it is not a request'
      using errcode = '22023';
  end if;

  insert into purchase_requests (
    org_id, requested_by, assigned_to, job_id, needed_by, notes, supplier_id
  ) values (
    v_org, auth_user_id(), p_assigned_to, p_job_id, p_needed_by,
    nullif(btrim(coalesce(p_notes, '')), ''), p_supplier_id
  )
  returning * into v_request;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    if coalesce(btrim(v_line ->> 'description'), '') = '' then
      raise exception 'Every line needs to say what it is' using errcode = '22023';
    end if;
    if coalesce((v_line ->> 'quantity')::numeric, 0) <= 0 then
      raise exception 'Every line needs a quantity' using errcode = '22023';
    end if;

    insert into purchase_request_lines (
      org_id, request_id, item_id, description, quantity, unit, estimated_unit_cost
    ) values (
      v_org, v_request.id,
      nullif(v_line ->> 'item_id', '')::uuid,
      btrim(v_line ->> 'description'),
      (v_line ->> 'quantity')::numeric,
      coalesce(nullif(btrim(coalesce(v_line ->> 'unit', '')), ''), 'each'),
      nullif(v_line ->> 'estimated_unit_cost', '')::numeric
    );
  end loop;

  -- Lines go on while it is still a draft, because the lock trigger stops a
  -- submitted request growing quietly after someone has looked at it.
  if p_submit then
    perform submit_purchase_request(v_request.id);
  end if;

  select * into v_request from purchase_requests where id = v_request.id;
  return v_request;
end;
$fn$;

comment on function create_purchase_request(jsonb, uuid, uuid, date, text, uuid, boolean) is
  'Raises a request with its lines and submits it, in one transaction — so a '
  'closed tab cannot leave an empty draft behind.';

-- ===========================================================
-- 0027_price_write_guard.sql
-- ===========================================================
-- 0027 Price is manager information to WRITE as well as to read
--
-- 0018 revoked the price columns from the signed-in role so a crew lead could
-- not read them. It only ever revoked SELECT. Writing them stayed wide open,
-- and the row policy on a draft change order did not pin its status, so:
--
--   a crew lead drafts a change order (which is his job),
--   sets amount = 50000 (a column he cannot read),
--   sets status = 'approved' (a decision that is not his),
--
-- and `job_contract_price()` — base price plus approved change orders — goes
-- up by fifty thousand. He never sees the number. The owner's margin moves.
--
-- Confirmed exploitable against the seed before this migration. Two holes,
-- fixed separately because either alone still leaves a way in.

-- ---------------------------------------------------------------------------
-- 1. A draft stays a draft
-- ---------------------------------------------------------------------------

-- The old policy checked who owned the row and not what they were turning it
-- into, so "update my own draft" included "approve my own draft".
drop policy if exists change_orders_own_draft on change_orders;
create policy change_orders_own_draft on change_orders for update
  using (created_by = auth_user_id() and status = 'draft')
  with check (
    created_by = auth_user_id()
    -- Moving off draft goes through present_change_order() and
    -- decide_change_order(), which check changeorder.manage.
    and status = 'draft'
  );

-- ---------------------------------------------------------------------------
-- 2. The price columns are not writable either
-- ---------------------------------------------------------------------------

-- The same shape as grant_columns_except() in 0018, for INSERT and UPDATE.
-- A column-level revoke cannot override a table-level grant, so the table
-- grant is dropped and every other column is granted back.
create or replace function grant_writes_except(p_table text, p_exclude text[])
returns void
language plpgsql
as $fn$
declare v_cols text;
begin
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    return;
  end if;

  execute format('revoke insert, update on %I from authenticated', p_table);

  select string_agg(quote_ident(column_name), ', ' order by ordinal_position)
    into v_cols
    from information_schema.columns
   where table_schema = 'public'
     and table_name = p_table
     and not (column_name = any (p_exclude));

  execute format('grant insert (%s), update (%s) on %I to authenticated',
                 v_cols, v_cols, p_table);
end;
$fn$;

comment on function grant_writes_except(text, text[]) is
  'Drops the table-level insert/update grant and re-grants every column but '
  'the excluded ones. Adding a column to a table this was run on means '
  'running it again, exactly like grant_columns_except().';

select grant_writes_except('jobs', array['quoted_price']);
select grant_writes_except('change_orders', array['amount']);
select grant_writes_except('profiles', array['cost_rate']);

-- ---------------------------------------------------------------------------
-- 3. The legitimate ways to write a price
-- ---------------------------------------------------------------------------

-- create_job() already carries a price and is definer, so booking work is
-- unaffected. Editing one needs its own door now.
create or replace function set_job_price(p_job_id uuid, p_quoted_price numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $fn$
declare v_old numeric;
begin
  if not has_permission('job.edit') then
    raise exception 'Not permitted: changing a job needs job.edit'
      using errcode = '42501';
  end if;
  -- Deliberately both flags: someone who cannot see the price has no business
  -- setting it, and could not tell you what they had changed it from.
  if not has_permission('price.view') then
    raise exception 'Not permitted: setting a price needs price.view'
      using errcode = '42501';
  end if;
  if p_quoted_price is not null and p_quoted_price < 0 then
    raise exception 'A price cannot be negative' using errcode = '22023';
  end if;

  select quoted_price into v_old from jobs
   where id = p_job_id and org_id = auth_org_id() and deleted_at is null;
  if not found then
    raise exception 'No such job' using errcode = '02000';
  end if;

  update jobs set quoted_price = p_quoted_price where id = p_job_id;
  return v_old;
end;
$fn$;

comment on function set_job_price(uuid, numeric) is
  'The only way a client sets a quoted price. Needs job.edit AND price.view; '
  'the column itself is no longer writable by the signed-in role.';

-- Drafting is the crew's; pricing is not. This exists so the field app can
-- raise one without touching the amount column at all.
create or replace function create_change_order(
  p_job_id uuid,
  p_title text,
  p_description text default null,
  p_added_hours numeric default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_id uuid;
begin
  if not has_permission('changeorder.draft') then
    raise exception 'Not permitted: raising a change order needs changeorder.draft'
      using errcode = '42501';
  end if;
  if p_title is null or btrim(p_title) = '' then
    raise exception 'Say what was found' using errcode = '22023';
  end if;
  if not can_see_job(p_job_id) then
    raise exception 'That is not your job' using errcode = '42501';
  end if;

  insert into change_orders (
    org_id, job_id, title, description, added_hours, status, created_by
  ) values (
    v_org, p_job_id, btrim(p_title),
    nullif(btrim(coalesce(p_description, '')), ''),
    p_added_hours, 'draft', auth_user_id()
  )
  returning id into v_id;

  -- Returns the id only. The row carries a price column the caller may well
  -- not be allowed to read.
  return v_id;
end;
$fn$;

comment on function create_change_order(uuid, text, text, numeric) is
  'Raises a draft change order with no price on it. The person who opens a '
  'wall and finds rot is the person who knows; pricing it is the manager''s.';

-- ===========================================================
-- 0028_crew_lead_sees_price.sql
-- ===========================================================
-- 0028 A crew lead sees what the job is worth
--
-- The crew lead is the person standing in the basement when the wall comes
-- off and there is twice as much rot behind it as anybody quoted for. Until
-- now he could write that up but not see the number it was being measured
-- against, so "this is bigger than the job" was a feeling rather than a
-- figure. Giving him the contract price makes the report he sends the office
-- worth acting on: not "there's more here", but "there's more here and we
-- quoted 8,600 for it".
--
-- Reading a price and moving one are different things, and after 0027 they
-- are enforced differently. Nothing here lets him move it:
--
--   * `jobs.quoted_price` and `change_orders.amount` are not writable by the
--     signed-in role at all — 0027 dropped the table grant and re-granted
--     every other column. No permission flag brings that back.
--   * `set_job_price()` needs job.edit AND price.view. A crew lead has
--     neither job.edit nor any way to get it.
--   * `present_change_order()` and `decide_change_order()` need
--     changeorder.manage. He has changeorder.draft, which raises a draft with
--     no price on it, and the row policy pins it there.
--
-- Three things price.view deliberately does NOT open, because they are
-- separate flags and stay that way:
--
--   * `costing.view` — what the job cost us, and the margin. Still manager
--     and owner only. He sees the price, not the profit.
--   * `user.view_cost_rates` — what his colleagues are paid. Owner only.
--   * The technician role. This is the lead's job, not the whole crew's.

create or replace function provision_org_roles(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into roles (org_id, key, name, is_system, permissions) values
  (p_org_id, 'owner', 'Owner', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.close', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.approve_unlimited', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'user.view_cost_rates', true,
    'role.manage', true, 'org.manage_settings', true, 'audit.view', true,
    'data.restore', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  (p_org_id, 'manager', 'Manager', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'audit.view', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  -- price.view, so he can tell the office the work has outgrown the quote.
  -- No costing.view: the price is not the margin.
  (p_org_id, 'crew_lead', 'Crew Lead', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true, 'inventory.transfer', true,
    'equipment.place', true,
    'time.log_others', true,
    'price.view', true
  )),

  -- Still no price. A technician is told what to do, not what it is worth.
  (p_org_id, 'technician', 'Technician', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true,
    'equipment.place', true
  )),

  -- Keeps the books, so needs the price but never the margin conversation.
  -- audit.view lets them read the trail; nothing here lets them change it.
  (p_org_id, 'bookkeeper', 'Bookkeeper', true, jsonb_build_object(
    'job.view_all', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'mileage.view_all', true, 'time.view_all', true,
    'audit.view', true, 'price.view', true, 'costing.view', true, 'export.run', true,
    'job.close', true
  ))
  on conflict (org_id, key) do nothing;
end;
$$;

-- Orgs that already exist. Only the system crew_lead role, and only where the
-- flag is not already set — an owner who turned it off by hand meant it.
update roles
   set permissions = permissions || '{"price.view": true}'::jsonb
 where key = 'crew_lead'
   and is_system
   and coalesce((permissions ->> 'price.view')::boolean, false) = false;

-- ===========================================================
-- 0029_crew_pay.sql
-- ===========================================================
-- 0029 What the crew was paid for the job
--
-- Crews here are paid a flat amount per job, not by the hour. Nothing records
-- hours and nothing should, so `job_labour_cost()` returned zero for every
-- job and `job_costs.margin` was contract price minus everything except the
-- largest cost on it. On a 9,850 job with a thousand pounds of materials and
-- equipment that reads as an 8,800 margin, which is not a small error — it is
-- the wrong answer to the only question the costing screens exist to answer.
--
-- One line per payment. The office records what was agreed, as one lump for
-- the crew or a line each, whichever matches how the job was actually paid.
--
-- Two decisions worth stating, because both could reasonably go the other way:
--
--   1. `user_id` is optional. "3,200 to Marcus's crew" is how a lot of these
--      get agreed, and forcing a split across names would invent detail that
--      was never decided. Name someone when the job was paid per person.
--
--   2. This is a cost, not payroll. It is what the job cost the company, so
--      it sits behind costing.view with margin and job cost, and it never
--      reaches the field app. What an individual takes home over a year is a
--      payroll question, and this app is not the place for it.

create table job_crew_pay (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  job_id uuid not null references jobs(id) on delete cascade,
  -- Optional: see decision 1 above.
  user_id uuid references profiles(id),
  amount numeric(12,2) not null check (amount >= 0),
  note text,
  recorded_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  deleted_by uuid references profiles(id),
  delete_reason text
);

create index job_crew_pay_job_idx on job_crew_pay (job_id) where deleted_at is null;

comment on table job_crew_pay is
  'What the crew was paid for a job. Crews are paid per job, not per hour, so '
  'this is the labour cost — there are no hours to multiply by a rate.';

select attach_updated_at('job_crew_pay');
select enable_rls('job_crew_pay');
select attach_audit('job_crew_pay');

-- ---------------------------------------------------------------------------
-- Who may see it, and who may record it
-- ---------------------------------------------------------------------------
--
-- Unlike a price, this needs no masking view: the whole row is a cost, so
-- there is nothing on it to show someone who may not see costs. That makes it
-- a row-level rule, which is what RLS is for.
--
-- Reading is costing.view — the same flag as job cost and margin, which is
-- what this feeds. The crew lead holds price.view and not costing.view, so he
-- sees what the job is worth and not what it cost, which is the line 0028
-- drew.

create policy job_crew_pay_select on job_crew_pay for select
  using (
    org_id = auth_org_id()
    and has_permission('costing.view')
    and (deleted_at is null or has_permission('audit.view'))
  );

-- Writing needs both flags, the same shape as set_job_price(): someone who
-- cannot see what a job cost has no business setting part of it, and could
-- not tell you what they had changed it from.
create policy job_crew_pay_write on job_crew_pay for all
  using (
    org_id = auth_org_id()
    and has_permission('costing.view')
    and has_permission('job.edit')
  )
  with check (
    org_id = auth_org_id()
    and has_permission('costing.view')
    and has_permission('job.edit')
  );

-- Removing one is a soft delete like everything else, so it goes in the
-- registry and comes back through restore_record().
insert into deletable_tables
  (table_name, label, title_column, ref_column, write_permission, parent_table, parent_fk, sort)
values
  ('job_crew_pay', 'Crew pay', 'note', null, 'job.edit', 'jobs', 'job_id', 35);

-- ---------------------------------------------------------------------------
-- Into the costing
-- ---------------------------------------------------------------------------

-- Both of these are `security definer`, and the reason is worth writing down
-- because getting it wrong breaks the costing screens with a permission error.
--
-- `job_labour_cost()` reads `profiles.cost_rate`, which is revoked from the
-- signed-in role. It got away with that as a one-line SQL function because
-- Postgres inlined it into `job_costs`, whose own definer rights covered the
-- read. Adding a second term to it makes inlining a planner's decision rather
-- than a certainty, and the day it declines, every costing screen returns
-- "permission denied for table profiles" to a manager who has done nothing
-- wrong. Definer rights make it deterministic instead of lucky.
--
-- Which means each needs its own gate, since a definer function is reachable
-- directly and RLS no longer applies inside it. Both check costing.view, the
-- same flag `job_costs` checks, so nothing is readable through the function
-- that was not already readable through the view.

create or replace function job_crew_pay_total(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select case
    when not has_permission('costing.view') then
      -- Not an error: this is called per row from a view that has already
      -- excluded anyone without the flag. Reached directly, it says nothing.
      null
    else coalesce((
      select sum(cp.amount)
      from job_crew_pay cp
      join jobs j on j.id = cp.job_id
      where cp.job_id = p_job_id
        and cp.deleted_at is null
        and j.org_id = auth_org_id()
    ), 0)
  end;
$$;

comment on function job_crew_pay_total(uuid) is
  'Flat crew payments recorded against a job. Definer rights, gated on '
  'costing.view and filtered to the caller''s org, exactly like job_costs.';

-- Both sources, added. The hourly half is zero today and stays in place: an
-- hourly crew is the sort of thing a contractor adds later, and when they do,
-- this keeps working without a migration.
create or replace function job_labour_cost(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select case
    when not has_permission('costing.view') then null
    else
      coalesce((
        select sum(time_entry_hours(t) * coalesce(p.cost_rate, 0))
        from time_entries t
        join profiles p on p.id = t.user_id
        join jobs j on j.id = t.job_id
        where t.job_id = p_job_id
          and t.clock_out_at is not null
          and j.org_id = auth_org_id()
      ), 0)
      + coalesce(job_crew_pay_total(p_job_id), 0)
  end;
$$;

comment on function job_labour_cost(uuid) is
  'Labour on a job: flat crew payments, plus hours times cost rate if anyone '
  'ever records hours. Crews are paid per job here, so in practice it is the '
  'first term. Definer rights, gated on costing.view — see the note above.';

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select, insert, update, delete on job_crew_pay to authenticated';
  end if;
end $$;

-- ===========================================================
-- 0030_gate_readable_by_the_crew.sql
-- ===========================================================
-- 0030 The completion gate has to be readable by the person it is for
--
-- `job_completion_blockers()` and `job_completion_warnings()` both start with
--
--   select * into v_job from jobs where id = p_job_id;
--
-- and 0027 revoked the price columns on `jobs` from the signed-in role, which
-- makes `select *` there fail by design. Both functions are invoker-rights, so
-- since 0027 every client call has raised
--
--   permission denied for table jobs
--
-- The write path was never affected: `transition_job()` is security definer,
-- so when it checks the gate internally the check runs with its own rights. A
-- job missing its photos could not be completed and still cannot be.
--
-- What broke is the screen that exists to tell a crew what is missing *before
-- they drive away*. The error came back as a null list, the app read that as
-- an empty list, and the completion card said "Nothing outstanding" over an
-- enabled button. Tapping it got a refusal from the server naming a photo
-- nobody had been asked for. The gate was never open; it just stopped
-- explaining itself.
--
-- Definer rights, and a visibility check of their own — a definer function is
-- reachable with any job id, and `can_see_job()` is the same test RLS applies
-- to the row.

create or replace function job_completion_blockers(p_job_id uuid)
returns text[]
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_job jobs;
  v_req jsonb;
  v_blockers text[] := '{}';
  v_form jsonb;
  v_pending int;
begin
  -- Only a client call needs checking. A direct database session — a
  -- migration, a maintenance query, the assertion suite — has no jwt claim at
  -- all, and refusing those would make the function unusable from psql for no
  -- gain: anyone with a database session can read the table anyway.
  if auth_user_id() is not null and not can_see_job(p_job_id) then
    return array['Job not found'];
  end if;

  select * into v_job from jobs where id = p_job_id and deleted_at is null;
  if v_job.id is null then
    return array['Job not found'];
  end if;

  select coalesce(t.completion_requirements, '{}'::jsonb) into v_req
  from job_templates t where t.id = v_job.template_id;
  v_req := coalesce(v_req, '{}'::jsonb);

  if coalesce((v_req ->> 'photos_before')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'before' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'Before photos required');
  end if;

  if coalesce((v_req ->> 'photos_after')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'after' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'After photos required');
  end if;

  if coalesce((v_req ->> 'customer_signature')::boolean, false)
     and not exists (
       select 1 from signatures where job_id = p_job_id and kind = 'completion'
     ) then
    v_blockers := array_append(v_blockers, 'Customer sign-off required');
  end if;

  for v_form in select * from jsonb_array_elements(coalesce(v_req -> 'forms', '[]'::jsonb)) loop
    if not exists (
      select 1
      from form_submissions s
      join form_templates ft on ft.id = s.template_id
      where s.job_id = p_job_id
        and ft.key = (v_form #>> '{}')
        and s.is_complete
    ) then
      v_blockers := array_append(v_blockers, 'Form not complete: ' || (v_form #>> '{}'));
    end if;
  end loop;

  -- Equipment left at a site with no collection arranged stays blocking. It is
  -- the one thing on this list that becomes invisible the moment the crew
  -- leaves, and a forgotten scrubber costs more than the tap it takes to set
  -- a date. The completion screen offers "schedule pickup" inline.
  if exists (
    select 1
    from equipment_assignments a
    where a.job_id = p_job_id
      and a.kind = 'site_staging'
      and a.ended_at is null
      and a.expected_end_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Equipment still staged at site with no pickup scheduled');
  end if;

  -- Money the customer has not answered on yet. Once the crew drives away it
  -- is never collected, so this one is worth the friction.
  select count(*) into v_pending
  from change_orders where job_id = p_job_id and status in ('draft', 'presented');

  if v_pending > 0 then
    v_blockers := array_append(v_blockers,
      v_pending || ' change order(s) not yet agreed with the customer');
  end if;

  return v_blockers;
end;
$$;

comment on function job_completion_blockers(uuid) is
  'What stands between this job and done. Definer rights because it reads '
  'jobs, whose price columns are revoked from the signed-in role; gated on '
  'can_see_job(), which is the same test RLS applies to the row.';

create or replace function job_completion_warnings(p_job_id uuid)
returns text[]
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_warnings text[] := '{}';
  v_open int;
  v_rentals int;
begin
  -- Same as the blockers: a session with no jwt claim is not a client call.
  if auth_user_id() is not null and not can_see_job(p_job_id) then
    return '{}';
  end if;

  select count(*) into v_open
  from time_entries where job_id = p_job_id and clock_out_at is null;

  if v_open > 0 then
    v_warnings := array_append(v_warnings,
      v_open || ' person(s) will be clocked out now');
  end if;

  -- Any rental still with us at completion, date set or not. "Job finished,
  -- vendor still has gear out" is the signal the office needs; whether a
  -- return date exists is a detail.
  select count(*) into v_rentals
  from equipment_rentals
  where job_id = p_job_id
    and status in ('on_hire', 'overdue');

  if v_rentals > 0 then
    v_warnings := array_append(v_warnings,
      v_rentals || ' rental(s) still out — the office will be told');
  end if;

  return v_warnings;
end;
$$;

comment on function job_completion_warnings(uuid) is
  'True, worth saying, nobody''s reason to stand in a driveway. Definer for '
  'the same reason as the blockers, and gated the same way.';

-- ===========================================================
-- 0031_book_a_new_customer.sql
-- ===========================================================
-- 0031 Booking work for somebody who is not in the system yet
--
-- Every job here starts with a phone call from a stranger. The booking form
-- asked which customer, which site — and on a fresh organisation both lists
-- were empty, so the one thing an owner wants to do on day one was the one
-- thing the app would not let them do. The way through was Customers → add,
-- then that customer → add a site, then back to Jobs → new: three screens
-- before a single job exists.
--
-- This takes the customer and the site as either an id or the few words it
-- takes to create one, and then hands the actual booking to `create_job()`.
-- Deliberately a wrapper and not a copy: every rule about double bookings,
-- time off, work days and crew lives in that function and must keep living in
-- exactly one place.
--
-- One function means one transaction, which is the point. A refused booking
-- — a crew member already out that day — must not leave a half-made customer
-- behind for somebody to find later and wonder about.

create or replace function create_job_with_site(
  -- An existing customer, or the name and number to make one.
  p_customer_id uuid,
  p_customer_name text,
  p_customer_phone text,
  -- An existing site, or the label and address to make one.
  p_site_id uuid,
  p_site_label text,
  p_site_address1 text,
  p_site_city text,
  p_site_state text,
  p_site_postal text,
  -- The job itself, passed straight through.
  p_title text,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_description text default null,
  p_template_id uuid default null,
  p_priority job_priority default 'normal',
  p_quoted_price numeric default null,
  p_crew uuid[] default '{}'
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_customer uuid := p_customer_id;
  v_site uuid := p_site_id;
begin
  -- Making a customer or a site is the office's job, and a separate one from
  -- booking work. Someone who may book but not manage customers can still
  -- book against the ones that exist.
  if (p_customer_id is null or p_site_id is null)
     and not has_permission('customer.manage') then
    raise exception 'Not permitted: adding a customer or site needs customer.manage'
      using errcode = '42501';
  end if;

  if v_customer is null then
    if p_customer_name is null or btrim(p_customer_name) = '' then
      raise exception 'A new customer needs a name' using errcode = '22023';
    end if;
    insert into customers (org_id, name, phone, created_by)
    values (v_org, btrim(p_customer_name),
            nullif(btrim(coalesce(p_customer_phone, '')), ''), auth_user_id())
    returning id into v_customer;
  else
    -- An id from somewhere else is not a licence to read somebody else's
    -- books: this runs with definer rights, so the org check is ours to make.
    perform 1 from customers
     where id = v_customer and org_id = v_org and deleted_at is null;
    if not found then
      raise exception 'No such customer' using errcode = '02000';
    end if;
  end if;

  if v_site is null then
    if p_site_label is null or btrim(p_site_label) = '' then
      raise exception 'A new site needs a label — what the crew will call it'
        using errcode = '22023';
    end if;
    if p_site_address1 is null or btrim(p_site_address1) = '' then
      raise exception 'A new site needs a street address — the crew have to drive there'
        using errcode = '22023';
    end if;
    insert into sites (org_id, customer_id, label, address_line1, city, state,
                       postal_code, created_by)
    values (v_org, v_customer, btrim(p_site_label), btrim(p_site_address1),
            nullif(btrim(coalesce(p_site_city, '')), ''),
            nullif(btrim(coalesce(p_site_state, '')), ''),
            nullif(btrim(coalesce(p_site_postal, '')), ''),
            auth_user_id())
    returning id into v_site;
  else
    perform 1 from sites
     where id = v_site and customer_id = v_customer and org_id = v_org
       and deleted_at is null;
    if not found then
      raise exception 'That site does not belong to that customer'
        using errcode = '22023';
    end if;
  end if;

  return create_job(
    v_customer, v_site, p_title, p_scheduled_start, p_scheduled_end,
    p_description, p_template_id, p_priority, p_quoted_price, p_crew
  );
end;
$fn$;

comment on function create_job_with_site is
  'Books a job, making the customer and/or the site first when they are new. '
  'A wrapper around create_job(), which keeps every scheduling rule; this '
  'only adds the two rows a first-time caller needs and the transaction that '
  'ties all of it together.';

-- ===========================================================
-- 0032_how_the_job_was_settled.sql
-- ===========================================================
-- 0032 How the job was settled, as a note to the office
--
-- READ THE SCOPE BOUNDARY BEFORE EXTENDING THIS. This app tracks what a job
-- cost us; what a customer owes lives in the finance system and must stay
-- there. This column does not change that and must not be grown into it.
--
-- What it is: the crew are standing at the door, the customer hands over cash
-- or taps a card, and that fact is useful to whoever does the books tomorrow.
-- Recording "cash" is the same kind of thing as recording which van went —
-- an observation from site, passed on.
--
-- What it deliberately is not:
--
--   * There is no amount. The crew do not know the number and should not be
--     asked to guess it; the price is the office's and the invoice is the
--     finance system's.
--   * There is no "unpaid" value. Nothing collected means the column stays
--     null — an absence of a note, not a balance. The moment this can answer
--     "has this been paid?" it has become a second, worse source of financial
--     truth, and the two will drift.
--
-- If someone asks for an amount or a paid flag, that is the conversation about
-- the boundary, not a column.

create type settlement_method as enum ('cash', 'card', 'interac');

alter table jobs
  add column if not exists settlement_method settlement_method,
  add column if not exists settled_at timestamptz,
  add column if not exists settled_by uuid references profiles(id);

comment on column jobs.settlement_method is
  'How the customer settled at the door, as told to the crew. Null means '
  'nothing was recorded, which is not the same as unpaid. No amount here by '
  'design — see the scope boundary.';

-- Adding a column to jobs means re-running BOTH grant helpers, or the new
-- column is readable and writable by everyone while quoted_price quietly
-- becomes so too: both helpers rebuild the whole grant from the column list.
select grant_columns_except('jobs', array['quoted_price']);
select grant_writes_except('jobs', array['quoted_price']);

-- ---------------------------------------------------------------------------
-- Finishing a job
-- ---------------------------------------------------------------------------

create or replace function complete_job(
  p_job_id uuid,
  p_settlement_method settlement_method default null,
  p_note text default null
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare v_job jobs;
begin
  -- transition_job() owns the rules — the permission, the gate, the history
  -- row. This adds the two things the crew are asked for at the same moment,
  -- in the same transaction, so a refused completion records neither.
  if p_settlement_method is not null or nullif(btrim(coalesce(p_note, '')), '') is not null then
    if not can_see_job(p_job_id) then
      raise exception 'That is not your job' using errcode = '42501';
    end if;
  end if;

  v_job := transition_job(p_job_id, 'work_complete', null);

  if p_settlement_method is not null then
    update jobs
       set settlement_method = p_settlement_method,
           settled_at = now(),
           settled_by = auth_user_id()
     where id = p_job_id;
  end if;

  if nullif(btrim(coalesce(p_note, '')), '') is not null then
    insert into job_comments (org_id, job_id, author_id, body)
    values (v_job.org_id, p_job_id, auth_user_id(), btrim(p_note));
  end if;

  select * into v_job from jobs where id = p_job_id;
  return v_job;
end;
$fn$;

comment on function complete_job(uuid, settlement_method, text) is
  'Marks a job done, with how it was settled and anything the crew want to '
  'say, in one transaction. Delegates the status change to transition_job(), '
  'which keeps the completion gate and the permission check.';

-- ---------------------------------------------------------------------------
-- And onto the view the clients actually read
-- ---------------------------------------------------------------------------
--
-- jobs_safe lists its columns one by one, so a column added to `jobs` does
-- not appear on it. Nothing errors: the app asks for a column the view has
-- never heard of, PostgREST refuses the whole query, and the page decides the
-- job does not exist. A 404 on a job that is right there.
--
-- Re-stated in full rather than patched, because a view cannot have a column
-- appended — `create or replace` has to agree with the existing column order.

create or replace view jobs_safe as
select
  j.id, j.org_id, j.job_number, j.customer_id, j.site_id, j.template_id,
  j.title, j.description, j.status, j.priority,
  j.scheduled_start, j.scheduled_end, j.actual_start, j.actual_end,
  case when has_permission('price.view') then j.quoted_price end as quoted_price,
  case when has_permission('price.view') then job_contract_price(j.id) end as contract_price,
  case when has_permission('price.view') then job_change_order_total(j.id) end as change_order_total,
  j.insurance_claim_no, j.adjuster_contact, j.recurrence_rule, j.parent_job_id,
  j.blocked_reason, j.cancelled_reason, j.created_by, j.created_at, j.updated_at,
  -- Not behind price.view: how somebody paid at the door is not the price,
  -- and the crew who were handed the cash are the ones who reported it.
  j.settlement_method, j.settled_at, j.settled_by
from jobs j
where j.deleted_at is null
  and j.org_id = auth_org_id()
  and can_see_job(j.id);

comment on view jobs_safe is
  'Jobs as a field user may read them: price masked unless price.view. Definer '
  'rights, org filter applied explicitly. Adding a column to jobs means adding '
  'it here too — the list is explicit and a missing column reads as a 404.';

-- ===========================================================
-- 0033_job_numbers_that_tell_nobody_anything.sql
-- ===========================================================
-- 0033 Job numbers that do not announce how much work we have
--
-- They were a global sequence: J00001, J00002, J00003. Every job carried a
-- running total of every job the company had ever booked, and it was printed
-- at the top of the screen a customer is looking over your shoulder at. The
-- second job we ever quoted said so.
--
-- The new shape is YYMM-NNNN — 2610-4827 for October 2026 — where the last
-- four digits are random. It still sorts and groups by month, which is what
-- the office actually uses a job number for, and it is four digits anybody
-- can read down a phone line. What it no longer carries is a count.
--
-- The month comes from the day the work is booked for, in the organisation's
-- own timezone, not the server's. A job booked at 8pm in Springfield on the
-- 31st belongs to that month, and `now()` in UTC would have said the next.
--
-- Numbers already issued in the old format are renumbered below. Nothing
-- points at a job number — it is a label for people, and the foreign keys all
-- use the id — so this is safe, and leaving two formats side by side would
-- only invite someone to read meaning into the difference.

-- ---------------------------------------------------------------------------
-- Minting one
-- ---------------------------------------------------------------------------

create or replace function next_job_number(p_org uuid, p_when timestamptz default null)
returns text
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_zone text;
  v_stem text;
  v_try  text;
begin
  select timezone into v_zone from organizations where id = p_org;
  v_stem := to_char(coalesce(p_when, now()) at time zone coalesce(v_zone, 'UTC'), 'YYMM');

  -- Definer rights on purpose: the uniqueness check has to see every job in
  -- the organisation, and the person booking one generally cannot. Under the
  -- caller's rights a technician would be checking against the three jobs
  -- they can see and handing out a number already in use.
  for _ in 1..200 loop
    v_try := v_stem || '-' || lpad((floor(random() * 10000))::int::text, 4, '0');
    if not exists (select 1 from jobs where org_id = p_org and job_number = v_try) then
      return v_try;
    end if;
  end loop;

  -- Two hundred misses means the month is close to full at four digits —
  -- several thousand jobs in one month, which is not this company, but a
  -- number has to come back. Widen rather than fail or loop forever.
  return v_stem || '-' || lpad((floor(random() * 100000))::int::text, 5, '0');
end;
$fn$;

comment on function next_job_number(uuid, timestamptz) is
  'A free job number for an organisation, as YYMM-NNNN in that organisation''s '
  'timezone. Random within the month so the number carries no running total.';

-- ---------------------------------------------------------------------------
-- Handing it out
-- ---------------------------------------------------------------------------
--
-- A trigger rather than a column default, because a default cannot read
-- another column of the row being inserted and this one needs two: the
-- organisation, to be unique within it, and the scheduled start, to know
-- which month it belongs to.
--
-- It only fills a number that was not given, so the seed data keeps its own
-- readable J00101-style numbers and the assertions that name them keep
-- working.

create or replace function set_job_number()
returns trigger
language plpgsql
as $fn$
begin
  if new.job_number is null or btrim(new.job_number) = '' then
    new.job_number := next_job_number(new.org_id, new.scheduled_start);
  end if;
  return new;
end;
$fn$;

alter table jobs alter column job_number drop default;
alter table jobs alter column job_number drop not null;
drop sequence if exists job_number_seq;

drop trigger if exists jobs_number on jobs;
create trigger jobs_number before insert on jobs
  for each row execute function set_job_number();

-- Dropping NOT NULL above is what lets an insert leave the column out; the
-- trigger has filled it by the time the row lands, and this puts the
-- guarantee back so a later trigger change cannot quietly start writing
-- nameless jobs.
alter table jobs add constraint jobs_job_number_present
  check (job_number is not null and btrim(job_number) <> '');

-- ---------------------------------------------------------------------------
-- The ones already out there
-- ---------------------------------------------------------------------------

do $$
declare r record;
begin
  for r in
    select id, org_id, coalesce(scheduled_start, created_at) as booked_for
      from jobs
     where job_number ~ '^J[0-9]+$'
     order by created_at
  loop
    update jobs
       set job_number = next_job_number(r.org_id, r.booked_for)
     where id = r.id;
  end loop;
end $$;

-- ===========================================================
-- 0034_this_company_works_in_ontario.sql
-- ===========================================================
-- 0034 This company works in Ontario
--
-- The app was built against a Massachusetts stand-in — eastern US timezone,
-- dollars formatted as USD, mileage at the IRS rate per mile, moisture
-- readings in Fahrenheit. Ninety per cent of the work is in Ontario, so all
-- of that was quietly wrong, in the way that only shows up when somebody
-- reads a number off the screen and acts on it.
--
-- None of it is a schema change. The distance column was always called
-- `distance` and always came off an odometer, which in Ontario reads
-- kilometres; the money columns are plain numerics. What changes here is the
-- organisation's own settings and the one form template that named a unit.

-- ---------------------------------------------------------------------------
-- Timezone
-- ---------------------------------------------------------------------------
--
-- America/Toronto, not America/New_York. They have kept the same offset and
-- the same daylight-saving dates for decades, so nothing moves today — but
-- the two are separate entries in the database precisely because that is not
-- promised, and a company in Ottawa should not have its working day defined
-- by a rule New York might change.

alter table organizations alter column timezone set default 'America/Toronto';

update organizations
   set timezone = 'America/Toronto'
 where timezone = 'America/New_York';

-- ---------------------------------------------------------------------------
-- What a kilometre is worth
-- ---------------------------------------------------------------------------
--
-- 0.67 was the IRS rate per MILE. The CRA publishes a per-kilometre
-- allowance instead, and at the time of writing the published figure for the
-- first 5,000 km is reported as either 72 or 73 cents depending on who you
-- ask. 0.72 is set here as the conservative one.
--
-- CHECK IT AND CHANGE IT. It is a setting rather than a column for exactly
-- this reason — the rate moves every year, and no migration should be needed:
--
--   update organizations
--      set settings = jsonb_set(settings, '{mileage_rate}', '0.73');

alter table organizations alter column settings set default jsonb_build_object(
  'mileage_rate', 0.72,
  'approval_threshold', 500,
  'geofence_radius_m', 150,
  'acceptance_escalation_hours', 12
);

update organizations
   set settings = jsonb_set(settings, '{mileage_rate}', '0.72')
 where (settings ->> 'mileage_rate')::numeric = 0.67;

-- ---------------------------------------------------------------------------
-- Degrees
-- ---------------------------------------------------------------------------
--
-- The moisture readings form asked for a temperature in Fahrenheit. A crew
-- in Ontario carries a meter that reads Celsius, and the mismatch is the
-- dangerous kind: 20 is a plausible number in both scales and means two
-- completely different rooms.
--
-- Readings already recorded keep their old `temp_f` key and are NOT
-- converted — reinterpreting numbers somebody wrote down is worse than
-- leaving them legible. There are none yet; if that changes, convert them
-- deliberately rather than here.

create or replace function provision_org_forms(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into form_templates (org_id, key, name, description, is_per_room, fields) values
  (p_org_id, 'moisture_readings', 'Moisture Readings', 'Per-room moisture and psychrometric readings', true,
   '[
     {"key":"material","label":"Material","type":"select","required":true,
      "options":["Drywall","Wood framing","Subfloor","Concrete","Insulation","Other"]},
     {"key":"moisture_pct","label":"Moisture content","type":"number","unit":"%","required":true},
     {"key":"temp_c","label":"Temperature","type":"number","unit":"C","required":true},
     {"key":"rh_pct","label":"Relative humidity","type":"number","unit":"%","required":true},
     {"key":"gpp","label":"Grains per pound","type":"number","unit":"gpp","required":false},
     {"key":"notes","label":"Notes","type":"text","required":false}
   ]'::jsonb),

  (p_org_id, 'containment_check', 'Containment Verification', 'Containment and negative pressure check', false,
   '[
     {"key":"barrier_intact","label":"Barrier intact","type":"boolean","required":true},
     {"key":"negative_pressure","label":"Negative pressure confirmed","type":"boolean","required":true},
     {"key":"pressure_reading","label":"Pressure differential","type":"number","unit":"inWC","required":false},
     {"key":"scrubbers_running","label":"Air scrubbers running","type":"number","required":true},
     {"key":"decon_setup","label":"Decontamination chamber set up","type":"boolean","required":true},
     {"key":"notes","label":"Notes","type":"text","required":false}
   ]'::jsonb),

  (p_org_id, 'ppe_safety', 'PPE and Job Hazard Check', 'Pre-work safety check', false,
   '[
     {"key":"respirator","label":"Respirator worn and fit-tested","type":"boolean","required":true},
     {"key":"suit","label":"Coveralls worn","type":"boolean","required":true},
     {"key":"gloves","label":"Gloves worn","type":"boolean","required":true},
     {"key":"eye","label":"Eye protection worn","type":"boolean","required":true},
     {"key":"hazards","label":"Hazards noted on site","type":"text","required":false}
   ]'::jsonb)
  on conflict (org_id, key) do nothing;
end;
$$;

-- And the organisations that already have the Fahrenheit version.
update form_templates
   set fields = (
         select jsonb_agg(
           case when f ->> 'key' = 'temp_f'
                then jsonb_build_object('key', 'temp_c', 'label', 'Temperature',
                                        'type', 'number', 'unit', 'C', 'required', true)
                else f end
           order by ord)
           from jsonb_array_elements(fields) with ordinality as t(f, ord)
       )
 where key = 'moisture_readings'
   and fields @> '[{"key": "temp_f"}]'::jsonb;

-- ===========================================================
-- 0035_what_kind_of_job_it_is.sql
-- ===========================================================
-- 0035 What kind of job it is
--
-- There was one classification on a job: `template_id`, the "kind of work",
-- which exists to drive the completion gate — what has to be photographed
-- and filled in before the crew may call it done. It is optional, and most
-- jobs are booked without one.
--
-- That is a checklist, not a category. The business does two different
-- things — it remediates and it inspects — and nothing on a job said which.
-- A question as ordinary as "how many inspections did we do last month" had
-- no answer, and the board could not tell a half-day inspection from a
-- three-day strip-out.
--
-- So the category sits on the job itself and is never null. It is not
-- derived from the template, because a job with no template still has a
-- kind; and templates now carry one too, so choosing Inspection narrows the
-- checklist list to the inspection checklists.
--
-- An enum rather than a table: three values that describe what the company
-- does, which is the sort of thing that changes on the scale of years. A
-- fourth is one line — `alter type job_category add value 'restoration'` —
-- and does not need a table nobody will ever open a screen to manage.

create type job_category as enum ('remediation', 'inspection', 'other');

alter table jobs
  add column if not exists category job_category not null default 'remediation';
alter table job_templates
  add column if not exists category job_category not null default 'remediation';

comment on column jobs.category is
  'What kind of work this is, for the office. Separate from template_id, '
  'which is the completion checklist and may be null.';

-- The checklists that already exist, sorted into the two kinds. Named rather
-- than guessed at: "Mold Inspection" and "Post-Remediation Verification" are
-- both someone going to look at something and write it down.
update job_templates
   set category = 'inspection'
 where name ilike '%inspection%'
    or name ilike '%verification%'
    or name ilike '%assessment%';

-- Adding a column to jobs means re-running BOTH grant helpers, or the new
-- column is readable and writable by everyone while quoted_price quietly
-- becomes so too: both rebuild the whole grant from the column list.
select grant_columns_except('jobs', array['quoted_price']);
select grant_writes_except('jobs', array['quoted_price']);

-- ---------------------------------------------------------------------------
-- And onto the view the clients read
-- ---------------------------------------------------------------------------
--
-- jobs_safe lists its columns explicitly, so a column added to `jobs` does
-- not appear on it. The app then asks for a column the view has never heard
-- of, PostgREST refuses the whole query, and the page reports the job
-- missing. That is how 0032 broke a live job page.
--
-- `category` goes on the END of the list, next to the 0032 columns, and not
-- beside `priority` where it belongs by meaning. `create or replace view`
-- matches the existing columns by position, so inserting one in the middle
-- is read as renaming `scheduled_start` to `category` and refused. New
-- columns append; the tidy order would need the view dropped, and dropping
-- it takes everything built on it with it.

create or replace view jobs_safe as
select
  j.id, j.org_id, j.job_number, j.customer_id, j.site_id, j.template_id,
  j.title, j.description, j.status, j.priority,
  j.scheduled_start, j.scheduled_end, j.actual_start, j.actual_end,
  case when has_permission('price.view') then j.quoted_price end as quoted_price,
  case when has_permission('price.view') then job_contract_price(j.id) end as contract_price,
  case when has_permission('price.view') then job_change_order_total(j.id) end as change_order_total,
  j.insurance_claim_no, j.adjuster_contact, j.recurrence_rule, j.parent_job_id,
  j.blocked_reason, j.cancelled_reason, j.created_by, j.created_at, j.updated_at,
  j.settlement_method, j.settled_at, j.settled_by,
  j.category
from jobs j
where j.deleted_at is null
  and j.org_id = auth_org_id()
  and can_see_job(j.id);

comment on view jobs_safe is
  'Jobs as a field user may read them: price masked unless price.view. Definer '
  'rights, org filter applied explicitly. Adding a column to jobs means adding '
  'it here too — the list is explicit and a missing column reads as a 404.';

-- ---------------------------------------------------------------------------
-- Booking one
-- ---------------------------------------------------------------------------
--
-- Dropped and recreated rather than `create or replace`, because a changed
-- parameter list makes a second function rather than replacing the first,
-- and two overloads differing by one defaulted argument are ambiguous to
-- call — every booking would start failing at once.

drop function if exists create_job_with_site(
  uuid, text, text, uuid, text, text, text, text, text, text,
  timestamptz, timestamptz, text, uuid, job_priority, numeric, uuid[]);
drop function if exists create_job(
  uuid, uuid, text, timestamptz, timestamptz, text, uuid, job_priority, numeric, uuid[]);

create function create_job(
  p_customer_id uuid,
  p_site_id uuid,
  p_title text,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_description text default null,
  p_template_id uuid default null,
  p_priority job_priority default 'normal',
  p_quoted_price numeric default null,
  p_crew uuid[] default '{}',
  p_category job_category default 'remediation'
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_job jobs;
  v_ok int;
begin
  if not has_permission('job.edit') then
    raise exception 'Not permitted: creating a job needs job.edit'
      using errcode = '42501';
  end if;

  if p_title is null or btrim(p_title) = '' then
    raise exception 'A job needs a title' using errcode = '22023';
  end if;
  if p_scheduled_start is null then
    raise exception 'A job needs a day' using errcode = '22023';
  end if;
  if p_scheduled_end is not null and p_scheduled_end < p_scheduled_start then
    raise exception 'The job ends before it starts' using errcode = '22023';
  end if;

  -- A site under the wrong customer is the mistake that produces a job
  -- history nobody can trust, so it is refused rather than tidied later.
  select count(*) into v_ok from sites
   where id = p_site_id and customer_id = p_customer_id and org_id = v_org
     and deleted_at is null;
  if v_ok = 0 then
    raise exception 'That site does not belong to that customer'
      using errcode = '23503';
  end if;

  insert into jobs (
    org_id, customer_id, site_id, template_id, title, description,
    priority, category, scheduled_start, scheduled_end, quoted_price, created_by
  ) values (
    v_org, p_customer_id, p_site_id, p_template_id, btrim(p_title),
    nullif(btrim(coalesce(p_description, '')), ''),
    coalesce(p_priority, 'normal'), coalesce(p_category, 'remediation'),
    p_scheduled_start, p_scheduled_end,
    p_quoted_price, auth_user_id()
  )
  returning * into v_job;

  perform rebuild_job_visits(v_job.id);

  -- A job created on the calendar is scheduled, not a draft: the draft state
  -- is for work being quoted, and this screen is for work being booked.
  perform transition_job(v_job.id, 'scheduled', 'Created on the calendar');

  if array_length(p_crew, 1) > 0 then
    perform set_job_crew(v_job.id, p_crew);
  end if;

  select * into v_job from jobs where id = v_job.id;
  return v_job;
end;
$fn$;

comment on function create_job(uuid, uuid, text, timestamptz, timestamptz, text, uuid, job_priority, numeric, uuid[], job_category) is
  'Creates a job, cuts its work days, schedules it and optionally assigns a '
  'crew — in one transaction, so a half-made job cannot be left behind.';

create function create_job_with_site(
  -- An existing customer, or the name and number to make one.
  p_customer_id uuid,
  p_customer_name text,
  p_customer_phone text,
  -- An existing site, or the label and address to make one.
  p_site_id uuid,
  p_site_label text,
  p_site_address1 text,
  p_site_city text,
  p_site_state text,
  p_site_postal text,
  -- The job itself, passed straight through.
  p_title text,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_description text default null,
  p_template_id uuid default null,
  p_priority job_priority default 'normal',
  p_quoted_price numeric default null,
  p_crew uuid[] default '{}',
  p_category job_category default 'remediation'
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_customer uuid := p_customer_id;
  v_site uuid := p_site_id;
begin
  -- Making a customer or a site is the office's job, and a separate one from
  -- booking work. Someone who may book but not manage customers can still
  -- book against the ones that exist.
  if (p_customer_id is null or p_site_id is null)
     and not has_permission('customer.manage') then
    raise exception 'Not permitted: adding a customer or site needs customer.manage'
      using errcode = '42501';
  end if;

  if v_customer is null then
    if p_customer_name is null or btrim(p_customer_name) = '' then
      raise exception 'A new customer needs a name' using errcode = '22023';
    end if;
    insert into customers (org_id, name, phone, created_by)
    values (v_org, btrim(p_customer_name),
            nullif(btrim(coalesce(p_customer_phone, '')), ''), auth_user_id())
    returning id into v_customer;
  else
    -- An id from somewhere else is not a licence to read somebody else's
    -- books: this runs with definer rights, so the org check is ours to make.
    perform 1 from customers
     where id = v_customer and org_id = v_org and deleted_at is null;
    if not found then
      raise exception 'No such customer' using errcode = '02000';
    end if;
  end if;

  if v_site is null then
    if p_site_label is null or btrim(p_site_label) = '' then
      raise exception 'A new site needs a label — what the crew will call it'
        using errcode = '22023';
    end if;
    if p_site_address1 is null or btrim(p_site_address1) = '' then
      raise exception 'A new site needs a street address — the crew have to drive there'
        using errcode = '22023';
    end if;
    insert into sites (org_id, customer_id, label, address_line1, city, state,
                       postal_code, created_by)
    values (v_org, v_customer, btrim(p_site_label), btrim(p_site_address1),
            nullif(btrim(coalesce(p_site_city, '')), ''),
            nullif(btrim(coalesce(p_site_state, '')), ''),
            nullif(btrim(coalesce(p_site_postal, '')), ''),
            auth_user_id())
    returning id into v_site;
  else
    perform 1 from sites
     where id = v_site and customer_id = v_customer and org_id = v_org
       and deleted_at is null;
    if not found then
      raise exception 'That site does not belong to that customer'
        using errcode = '22023';
    end if;
  end if;

  return create_job(
    v_customer, v_site, p_title, p_scheduled_start, p_scheduled_end,
    p_description, p_template_id, p_priority, p_quoted_price, p_crew, p_category
  );
end;
$fn$;

comment on function create_job_with_site(uuid, text, text, uuid, text, text, text, text, text, text, timestamptz, timestamptz, text, uuid, job_priority, numeric, uuid[], job_category) is
  'Books a job, making the customer and the site first if they are new — all '
  'in one transaction, so a refused booking leaves nothing behind.';

-- ===========================================================
-- 0036_the_office_can_administer_itself.sql
-- ===========================================================
-- 0036 The office can administer itself
--
-- An audit of the 39 permission flags against the screens found eleven that
-- the database enforces and no screen exercises. `user.manage`,
-- `org.manage_settings` and `role.manage` were the worst of them: the Owner
-- holds all three and had nothing to click, so adding a member of staff or
-- changing the spend threshold meant someone opening the SQL editor.
--
-- Almost all of that gap is screens, not schema — the row policies for every
-- one of those tables already exist and already check the right flag. Three
-- things genuinely need the database, and they are here.

-- ---------------------------------------------------------------------------
-- What somebody is paid
-- ---------------------------------------------------------------------------
--
-- `profiles.cost_rate` is revoked from `authenticated` for select AND for
-- update, so no client can write it however the policy reads — a column grant
-- cannot tell two signed-in users apart. Reading is already solved:
-- `profiles_safe` masks it behind `user.view_cost_rates`. Writing needs a
-- definer function, the same shape as `set_job_price()`.
--
-- Two flags, deliberately: managing people is not the same as being shown
-- what they are paid, and the pairing mirrors how crew pay works.

create or replace function set_cost_rate(p_user_id uuid, p_cost_rate numeric)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
begin
  if not has_permission('user.manage') then
    raise exception 'Not permitted: changing a person needs user.manage'
      using errcode = '42501';
  end if;
  if not has_permission('user.view_cost_rates') then
    raise exception 'Not permitted: setting a cost rate needs user.view_cost_rates'
      using errcode = '42501';
  end if;
  if p_cost_rate is not null and p_cost_rate < 0 then
    raise exception 'A cost rate cannot be negative' using errcode = '22023';
  end if;

  update profiles
     set cost_rate = p_cost_rate
   where id = p_user_id and org_id = auth_org_id();

  if not found then
    raise exception 'No such person here' using errcode = '02000';
  end if;
end;
$fn$;

comment on function set_cost_rate(uuid, numeric) is
  'Sets what somebody is paid. Needs user.manage AND user.view_cost_rates; '
  'the column is revoked from the client so nothing else can write it.';

-- ---------------------------------------------------------------------------
-- Adding a member of staff
-- ---------------------------------------------------------------------------
--
-- Signing in and being known to the app are two different things. Supabase
-- Authentication owns the password; `profiles` says who that person is here.
-- A client cannot create the login — that needs the service key, which must
-- never reach a browser — so the flow stays two steps: the login is made in
-- the Supabase dashboard, and this attaches it to the company.
--
-- Definer rights, because `auth.users` is not readable by a signed-in user.
-- That is also why this takes an email rather than an id: the person doing it
-- has no way to look the id up.
--
-- It refuses to create a second organisation, and it cannot: v_org is the
-- caller's own. That was the trap in the old add-a-person.sql.

create or replace function add_person(
  p_email text,
  p_full_name text,
  p_role_key text,
  p_phone text default null
)
returns profiles
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org     uuid := auth_org_id();
  v_user    uuid;
  v_role_id uuid;
  v_known   text;
  v_person  profiles;
begin
  if not has_permission('user.manage') then
    raise exception 'Not permitted: adding a person needs user.manage'
      using errcode = '42501';
  end if;
  if p_full_name is null or btrim(p_full_name) = '' then
    raise exception 'A person needs a name' using errcode = '22023';
  end if;

  select id into v_user from auth.users where lower(email) = lower(btrim(p_email));
  if v_user is null then
    raise exception
      'Nobody can sign in as % yet. Create the login first: Supabase '
      '-> Authentication -> Users -> Add user, with Auto Confirm ticked.',
      btrim(p_email)
      using errcode = '02000';
  end if;

  select id into v_role_id from roles where org_id = v_org and key = p_role_key;
  if v_role_id is null then
    select string_agg(key, ', ' order by key) into v_known from roles where org_id = v_org;
    raise exception 'No role called "%". The roles here are: %.', p_role_key, v_known
      using errcode = '22023';
  end if;

  -- Someone already here, being re-added: treat it as putting them back
  -- rather than refusing. Re-running this with a different role is how a
  -- promotion is recorded.
  insert into profiles (id, org_id, role_id, full_name, email, phone, is_active)
  values (v_user, v_org, v_role_id, btrim(p_full_name), lower(btrim(p_email)),
          nullif(btrim(coalesce(p_phone, '')), ''), true)
  on conflict (id) do update
     set org_id    = excluded.org_id,
         role_id   = excluded.role_id,
         full_name = excluded.full_name,
         email     = excluded.email,
         phone     = coalesce(excluded.phone, profiles.phone),
         is_active = true
  returning * into v_person;

  return v_person;
end;
$fn$;

comment on function add_person(text, text, text, text) is
  'Attaches an existing Supabase login to this organisation as a member of '
  'staff. Cannot create the login itself — that needs the service key — and '
  'cannot reach another organisation, because the org is the caller''s own.';

-- ---------------------------------------------------------------------------
-- The settings
-- ---------------------------------------------------------------------------
--
-- `organizations` already has an update policy checking org.manage_settings,
-- so a client could merge the jsonb itself. It should not: a client that
-- sends the whole `settings` object overwrites every key it did not know
-- about, so a screen written today silently deletes a setting added next
-- year. This takes the fields one at a time and leaves the rest alone.
--
-- Nulls mean "leave it", which is what lets one screen save only what it
-- shows.

create or replace function update_org_settings(
  p_name text default null,
  p_timezone text default null,
  p_mileage_rate numeric default null,
  p_approval_threshold numeric default null
)
returns organizations
language plpgsql
security definer
set search_path = public
as $fn$
declare v_org organizations;
begin
  if not has_permission('org.manage_settings') then
    raise exception 'Not permitted: changing settings needs org.manage_settings'
      using errcode = '42501';
  end if;
  if p_mileage_rate is not null and p_mileage_rate < 0 then
    raise exception 'A mileage rate cannot be negative' using errcode = '22023';
  end if;
  if p_approval_threshold is not null and p_approval_threshold < 0 then
    raise exception 'An approval threshold cannot be negative' using errcode = '22023';
  end if;
  -- A timezone the database does not recognise would make every date on every
  -- screen wrong at once, so it is checked rather than trusted.
  if p_timezone is not null
     and not exists (select 1 from pg_timezone_names where name = p_timezone) then
    raise exception 'There is no timezone called "%"', p_timezone using errcode = '22023';
  end if;

  update organizations
     set name     = coalesce(nullif(btrim(coalesce(p_name, '')), ''), name),
         timezone = coalesce(p_timezone, timezone),
         settings = settings
                    || case when p_mileage_rate is null then '{}'::jsonb
                            else jsonb_build_object('mileage_rate', p_mileage_rate) end
                    || case when p_approval_threshold is null then '{}'::jsonb
                            else jsonb_build_object('approval_threshold', p_approval_threshold) end
   where id = auth_org_id()
  returning * into v_org;

  return v_org;
end;
$fn$;

comment on function update_org_settings(text, text, numeric, numeric) is
  'Changes the organisation''s name, timezone and money settings one field at '
  'a time. Merges into settings rather than replacing it, so a screen cannot '
  'delete a key it was never told about.';

-- ===========================================================
-- 0037_kit_left_on_a_finished_job.sql
-- ===========================================================
-- 0037 Equipment left on a finished job
--
-- Finishing a job warned about rentals still out and said nothing about our
-- own equipment, so a crew could mark a job done and drive away leaving two
-- dehumidifiers in a basement with nothing anywhere recording that anybody
-- should go back for them.
--
-- A warning and not a blocker, on purpose. In this trade the kit is MEANT to
-- stay: dehus run for days after the work is finished, and refusing the
-- completion would teach the crew to leave jobs open instead, which loses
-- the completion date and the settlement note with it. The job finishes; the
-- app just stops being silent about what is still in the building.

create or replace function job_completion_warnings(p_job_id uuid)
returns text[]
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_warnings text[] := '{}';
  v_open int;
  v_rentals int;
  v_ours int;
begin
  -- Same as the blockers: a session with no jwt claim is not a client call.
  if auth_user_id() is not null and not can_see_job(p_job_id) then
    return '{}';
  end if;

  select count(*) into v_open
  from time_entries where job_id = p_job_id and clock_out_at is null;

  if v_open > 0 then
    v_warnings := array_append(v_warnings,
      v_open || ' person(s) will be clocked out now');
  end if;

  -- Any rental still with us at completion, date set or not. "Job finished,
  -- vendor still has gear out" is the signal the office needs; whether a
  -- return date exists is a detail.
  select count(*) into v_rentals
  from equipment_rentals
  where job_id = p_job_id
    and status in ('on_hire', 'overdue');

  if v_rentals > 0 then
    v_warnings := array_append(v_warnings,
      v_rentals || ' rental(s) still out — the office will be told');
  end if;

  -- And our own, which costs nothing in hire but is the thing that actually
  -- goes missing: a scrubber nobody collected is a scrubber nobody can find
  -- next week.
  --
  -- Staged with no pickup date is NOT counted here, because that case is
  -- already a blocker — the completion is refused outright. Counting it in
  -- both places would have the same job telling the crew "this stops you"
  -- and "this is fine, carry on" at once.
  select count(*) into v_ours
  from equipment_assignments
  where job_id = p_job_id
    and ended_at is null
    and not (kind = 'site_staging' and expected_end_at is null);

  if v_ours > 0 then
    v_warnings := array_append(v_warnings,
      v_ours || ' of our own unit(s) still out on this job — the job keeps '
      || 'showing them until somebody collects them');
  end if;

  return v_warnings;
end;
$$;

comment on function job_completion_warnings(uuid) is
  'True, worth saying, nobody''s reason to stand in a driveway. Definer for '
  'the same reason as the blockers, and gated the same way.';

-- ---------------------------------------------------------------------------
-- What is still in the building
-- ---------------------------------------------------------------------------
--
-- The crew screen needs to list it to offer a Collect button, and reading
-- `equipment_assignments` from the client means an embedded join through a
-- view to get the asset tag — which PostgREST has to infer a relationship
-- for and which cannot be checked without a live PostgREST. One function
-- instead, which the call checker does verify.

create or replace function job_equipment_on_site(p_job_id uuid)
returns table (
  assignment_id uuid,
  equipment_id uuid,
  asset_tag text,
  name text,
  kind equipment_placement_kind,
  started_at timestamptz,
  expected_end_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select a.id, e.id, e.asset_tag, e.name, a.kind, a.started_at, a.expected_end_at
  from equipment_assignments a
  join equipment e on e.id = a.equipment_id
  where a.job_id = p_job_id
    and a.ended_at is null
    and (auth_user_id() is null or can_see_job(p_job_id))
  order by e.asset_tag;
$$;

comment on function job_equipment_on_site(uuid) is
  'Our own units still placed against a job, open assignments only. Definer, '
  'and gated by can_see_job() exactly like the completion gate.';

-- ===========================================================
-- 0038_a_site_is_its_address.sql
-- ===========================================================
-- 0038 A site is its address
--
-- Booking asked for two things about a new address: the street address, and
-- "what the crew will call it". The second made sense when the first screens
-- were drawn and does not survive contact with the work: the crew call it
-- the address. Being asked to invent a nickname for 602 Cornell Centre Blvd,
-- while a customer is on the phone, is a question with no good answer and it
-- stops the booking until one is typed.
--
-- `sites.label` stays NOT NULL — it is on every screen that lists a site and
-- a nameless row would be a blank in a dropdown. What changes is who supplies
-- it: when the label is not given, the street address is the label. A site
-- somebody HAS named ("Larkspur Apts — unit 3B") keeps its name, which is
-- why this is a default and not a removal.

create or replace function create_job_with_site(
  -- An existing customer, or the name and number to make one.
  p_customer_id uuid,
  p_customer_name text,
  p_customer_phone text,
  -- An existing site, or the address to make one. The label is optional:
  -- leave it out and the street address becomes the name.
  p_site_id uuid,
  p_site_label text,
  p_site_address1 text,
  p_site_city text,
  p_site_state text,
  p_site_postal text,
  -- The job itself, passed straight through.
  p_title text,
  p_scheduled_start timestamptz,
  p_scheduled_end timestamptz default null,
  p_description text default null,
  p_template_id uuid default null,
  p_priority job_priority default 'normal',
  p_quoted_price numeric default null,
  p_crew uuid[] default '{}',
  p_category job_category default 'remediation'
)
returns jobs
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_org uuid := auth_org_id();
  v_customer uuid := p_customer_id;
  v_site uuid := p_site_id;
  v_label text;
begin
  -- Making a customer or a site is the office's job, and a separate one from
  -- booking work. Someone who may book but not manage customers can still
  -- book against the ones that exist.
  if (p_customer_id is null or p_site_id is null)
     and not has_permission('customer.manage') then
    raise exception 'Not permitted: adding a customer or site needs customer.manage'
      using errcode = '42501';
  end if;

  if v_customer is null then
    if p_customer_name is null or btrim(p_customer_name) = '' then
      raise exception 'A new customer needs a name' using errcode = '22023';
    end if;
    insert into customers (org_id, name, phone, created_by)
    values (v_org, btrim(p_customer_name),
            nullif(btrim(coalesce(p_customer_phone, '')), ''), auth_user_id())
    returning id into v_customer;
  else
    -- An id from somewhere else is not a licence to read somebody else's
    -- books: this runs with definer rights, so the org check is ours to make.
    perform 1 from customers
     where id = v_customer and org_id = v_org and deleted_at is null;
    if not found then
      raise exception 'No such customer' using errcode = '02000';
    end if;
  end if;

  if v_site is null then
    if p_site_address1 is null or btrim(p_site_address1) = '' then
      raise exception 'A new site needs a street address — the crew have to drive there'
        using errcode = '22023';
    end if;
    -- The address is the name unless somebody gave it one.
    v_label := coalesce(nullif(btrim(coalesce(p_site_label, '')), ''), btrim(p_site_address1));

    insert into sites (org_id, customer_id, label, address_line1, city, state,
                       postal_code, created_by)
    values (v_org, v_customer, v_label, btrim(p_site_address1),
            nullif(btrim(coalesce(p_site_city, '')), ''),
            nullif(btrim(coalesce(p_site_state, '')), ''),
            nullif(btrim(coalesce(p_site_postal, '')), ''),
            auth_user_id())
    returning id into v_site;
  else
    perform 1 from sites
     where id = v_site and customer_id = v_customer and org_id = v_org
       and deleted_at is null;
    if not found then
      raise exception 'That site does not belong to that customer'
        using errcode = '22023';
    end if;
  end if;

  return create_job(
    v_customer, v_site, p_title, p_scheduled_start, p_scheduled_end,
    p_description, p_template_id, p_priority, p_quoted_price, p_crew, p_category
  );
end;
$fn$;

comment on function create_job_with_site(uuid, text, text, uuid, text, text, text, text, text, text, timestamptz, timestamptz, text, uuid, job_priority, numeric, uuid[], job_category) is
  'Books a job, making the customer and the site first if they are new — all '
  'in one transaction, so a refused booking leaves nothing behind. A new '
  'site with no label is named after its street address.';


-- ===========================================================
-- Did it land?
-- ===========================================================
-- Printed by the same transaction that applied it, so there is no
-- second round trip to find out whether it worked. One column per
-- migration in this bundle: every one of them must read true.
select 'Applied' as result,
  to_regclass('public.deletable_tables') is not null as admin_mode_0022,
  exists (select 1 from pg_proc where proname = 'create_job') as job_authoring_0023,
  exists (select 1 from pg_proc where proname = 'decide_time_off') as decisions_0024,
  to_regclass('public.stock_packs') is not null as consumables_0025,
  exists (select 1 from pg_proc where proname = 'create_purchase_request') as purchasing_0026,
  exists (select 1 from pg_proc where proname = 'set_job_price') as price_guard_0027,
  exists (select 1 from roles where key = 'crew_lead' and is_system and (permissions ->> 'price.view')::boolean) as crew_lead_price_0028,
  to_regclass('public.job_crew_pay') is not null as crew_pay_0029,
  exists (select 1 from pg_proc where proname = 'job_completion_blockers' and prosecdef) as gate_readable_0030,
  exists (select 1 from pg_proc where proname = 'create_job_with_site') as new_customer_booking_0031,
  exists (select 1 from information_schema.columns where table_name = 'jobs_safe' and column_name = 'settlement_method') as settlement_0032,
  exists (select 1 from pg_proc where proname = 'next_job_number') as job_numbers_0033,
  exists (select 1 from information_schema.columns where table_name = 'organizations' and column_name = 'timezone' and column_default like '%America/Toronto%') as ontario_0034,
  exists (select 1 from information_schema.columns where table_name = 'jobs_safe' and column_name = 'category') as job_category_0035,
  exists (select 1 from pg_proc where proname = 'add_person') as office_admin_0036,
  exists (select 1 from pg_proc where proname = 'job_equipment_on_site') as kit_on_site_0037,
  exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'create_job_with_site' and p.prosrc like '%coalesce(nullif(btrim(coalesce(p_site_label%') as site_naming_0038,
  (select count(*) from information_schema.tables
    where table_schema = 'public') as tables,
  (select count(*) from pg_policies where schemaname = 'public') as policies;

commit;
